var QUESTOES_FONEMAS = [{"id":3,"enunciado":"Na análise dos sons da língua, distinguem-se unidades sonoras e representações gráficas. Considerando esse aspecto | linguístico, relacionado à fonética e à fonologia, assinale a alternativa CORRETA:","opcoes":["O fonema é a representação gráfica de um som da língua.","O dígrafo representa dois sons articulados de forma independente.","O encontro vocálico ocorre apenas quando há separação silábica.","O fonema corresponde à menor unidade sonora distintiva da língua."],"correta":3,"explicacao":"Gabarito: <strong>O fonema corresponde à menor unidade sonora distintiva da língua.</strong>.","banca":"Instituto Unique","ano":2025,"temas_relacionados":["fonemas"]},{"id":34,"enunciado":"Assinale a alternativa que NÃO apresenta uma palavra com encontro de consoantes.","opcoes":["Pai.","Livros.","Presente.","Diferente.","Armandinho."],"correta":0,"explicacao":"Gabarito: <strong>Pai.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":81,"enunciado":"Observe o meme a seguir: Imagem associada para resolução da questão - NÃO É PRA DEIXAR A TOALHA MOLHADA NA CAMA - NI I PR DIXIR I TOILHI MILHIDI NI CIMI Considerando a variedade linguística e os conceitos fonéticos relacionados à produção vocálica, analise as sentenças a seguir relativas ao enunciado “NI I PR DIXIR I TOILHI MILHIDI NI CIMI” (Não é pra deixar a toalha molhada na cama), presente na imagem, e assinale a alternativa CORRETA: I- A vogal “i”, em todas as suas ocorrências na frase, corresponde ao fonema /i/, caracterizado por ser uma vogal alta, anterior e fechada. II- Na palavra “DIXIR” (dizer), a vogal “i” faz parte de um ditongo oral decrescente, em que o fonema /i/ é seguido da semivogal /y/. III- A vogal “i”, na palavra “MILHIDI” (molhada), representa um hiato, ou seja, o encontro de duas vogais em sílabas diferentes. IV- Em todas as suas ocorrências na frase, a vogal “i” é articulada na região palatal, com a língua alta e os lábios retraídos.","opcoes":["Apenas as sentenças I e III são corretas.","Apenas as sentenças II e IV são corretas.","Apenas as sentenças I e IV são corretas.","Apenas as sentenças I, II e III são corretas."],"correta":2,"explicacao":"Gabarito: <strong>Apenas as sentenças I e IV são corretas.</strong>.","banca":"CONSULPAM","ano":2024,"temas_relacionados":["fonemas","ditongos","hiatos","silabas"]},{"id":120,"enunciado":"Julgue o item subsequente.\nA identificação e a classificação dos fonemas na língua portuguesa podem ser realizadas com precisão sem a necessidade de distinguir entre sons vocálicos e consonantais, uma vez que todos os fonemas compartilham propriedades acústicas e articulatórias semelhantes.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":143,"enunciado":"Em relação aos vocábulos salientados no texto, de acordo com Bechara, analise as assertivas abaixo, assinalando V, se verdadeiras, ou F, se falsas. ( ) Segundo o referido autor, algumas consoantes são grafadas com a mesma letra, fato que provoca dúvidas ortográficas; por outro lado, há letras que representam mais de um fonema, como é o caso da letra “x” em “complexo” (l. 01). ( ) São vogais nasais as que, em sua produção, ressoam nas fossas nasais. É um fenômeno de ressonância e não da saída do ar, o que opõe os fonemas orais aos nasais. Essa produção se evidencia no vocábulo “fundamentais” (linha 03). ( ) No português brasileiro, há tendência para inclusão de uma vogal epentética entre as consoantes desses encontros, de que decorre a pronúncia “adapitabilidade” (l. 02). A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V – V – V.","V – F – V.","F – V – F.","V – F – F.","F – F – V."],"correta":0,"explicacao":"Gabarito: <strong>V – V – V.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":273,"enunciado":"Sobre fonemas e fonética, assinale a alternativa incorreta, que se refere a palavras presentes no texto de Manuel Bandeira:","opcoes":["Que (l. 4) e quase (l. 4) trazem exemplos de dígrafo.","Assim (l. 1) e meu (l. 1) têm o mesmo número de fonemas.","Coisas (l. 2) e mais (l. 2) trazem exemplos de ditongo.","Suicidas (l. 6) e diamantes (l. 5) têm exemplos de hiato."],"correta":0,"explicacao":"Gabarito: <strong>Que (l. 4) e quase (l. 4) trazem exemplos de dígrafo.</strong>.","banca":"MSConcursos","ano":2016,"temas_relacionados":["fonemas","ditongos","hiatos","digrafos"]},{"id":312,"enunciado":"Sobre conceito de fonemas; relações entre fonemas e grafias; encontros vocálicos e consonantais, avalie as afirmações que seguem, assinalando V, se verdadeiras, ou F, se falsas. ( ) Encontro consonantal é a sequência de dois ou mais fonemas consonânticos numa palavra, podendo ocorrer na mesma sílaba ou em sílabas diferentes. ( ) Dígrafo é o grupo de duas letras representando um só fonema, podendo representar consoantes ou vogais nasais. ( ) Ditongo é a combinação de uma vogal e de uma semivogal, ou vice-versa; podendo ocorrer na mesma sílaba ou em sílabas diferentes. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V − V − V.","V − F − V.","F − V − F.","V − V − F.","F − F − V."],"correta":3,"explicacao":"Gabarito: <strong>V − V − F.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["fonemas","ditongos","digrafos","silabas","encontrosConsonantais","ortografia"]},{"id":321,"enunciado":"Analise as asserções a seguir e a relação proposta entre elas. I – Sobre Fonética e Fonologia, o vocábulo balanço, constante do primeiro parágrafo do texto, possui 7 letras, 6 fonemas, 3 sílabas e 1 ditongo PORQUE II – há a sequência de 7 letras seguintes: b-a-l-a-n-ç-o; 6 fonemas: [b], [a], [l], [ã], [ç], [u], 3 sílabas: ba -lan-ço e o dígrafo -an-. A respeito das asserções, é correto afirmar que","opcoes":["as duas são falsas.","a primeira é verdadeira, e a segunda é falsa.","a primeira é falsa, e a segunda é verdadeira.","as duas são verdadeiras, e a segunda justifica a primeira."],"correta":2,"explicacao":"Gabarito: <strong>a primeira é falsa, e a segunda é verdadeira.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["fonemas","ditongos","digrafos","silabas"]},{"id":340,"enunciado":"Analise as afirmações a seguir, relativamente à fonética e fonologia, de acordo com Bechara: I. Dígrafo é o emprego de duas letras para a representação gráfica de um só fonema. Há dígrafos que representam consoantes e dígrafos que representam vogais nasais. II. Chama-se encontro consonantal o seguimento imediato de duas ou mais consoantes de um mesmo vocábulo. Há encontros consonânticos pertencentes a mesma sílaba, ou a sílabas diferentes. III. Ditongo é o encontro de uma vogal e de uma semivogal, ou vice-versa, na mesma sílaba. Sendo a vogal a base da sílaba ou o elemento silábico, é ela o som vocálico que, no ditongo, se ouve mais distintamente. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2021,"temas_relacionados":["fonemas","ditongos","digrafos","silabas","encontrosConsonantais"]},{"id":445,"enunciado":"Assinale V, se verdadeiras ou F, se falsas nas seguintes afirmativas sobre palavras retiradas do texto. ( ) Em leigos, meio e animais, há ditongo. ( ) Em pesquisa, demanda e crescimento, há dígrafo. ( ) Em esquivamos, humanos e possibilidades, há mais letras do que fonemas. ( ) Em vegetais e majoritária, um mesmo fonema é representado por letras diferentes; já em origem e veganismo, uma mesma letra representa fonemas diferentes. A ordem correta de preenchimento dos parentes, de cima para baixo, é:","opcoes":["V – V – V – V.","V – F – V – F.","V – V – F – F.","F – V – V – V.","F – F – F – V."],"correta":0,"explicacao":"Gabarito: <strong>V – V – V – V.</strong>.","banca":"FUNDATEC","ano":2017,"temas_relacionados":["fonemas","ditongos","digrafos"]},{"id":473,"enunciado":"A palavra “nutricionista”, retirada do texto, tem quantas consoantes e quantas vogais?","opcoes":["6 consoantes e 7 vogais.","7 consoantes e 6 vogais.","8 consoantes e 5 vogais.","5 consoantes e 8 vogais.","9 consoantes e 4 vogais."],"correta":1,"explicacao":"Gabarito: <strong>7 consoantes e 6 vogais.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["fonemas"]},{"id":495,"enunciado":"Analise as assertivas que seguem, assinalando V, se verdadeiras, ou F, se falsas. ( ) Em ‘harmonia’, há sete fonemas, em virtude de ocorrer um dígrafo consonantal na primeira sílaba. ( ) A cada vogal ou grupo de sons pronunciados numa só expiração dá-se o nome de sílaba, que pode ser formada por uma vogal, um ditongo ou um tritongo; por uma vogal, um ditongo ou um tritongo acompanhados de consonantes. ( ) Dá-se o nome de encontro consonantal ao agrupamento de consoantes num vocábulo; havendo os inseparáveis e os separáveis. Tais ocorrência podem ser identificadas em ‘tradição’ e em ‘parte’. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["V – V – V.","V – F – F.","F – V – V.","V – F – V.","F – F – F."],"correta":2,"explicacao":"Gabarito: <strong>F – V – V.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["fonemas","ditongos","tritongos","digrafos","silabas","encontrosConsonantais"]},{"id":501,"enunciado":"Sobre a palavra “usuários”, em destaque no texto, é correto afirmar que:","opcoes":["não possui ditongos, nem poderia possuir, já que, nesse caso, não poderia receber qualquer tipo de acentuação gráfica.","possui três hiatos, todos formados pelas mesmas vogais, separando-se de maneira idêntica.","possui um hiato entre a segunda vogal “u”, na segunda sílaba, e a vogal “a”, na terceira sílaba.","no contexto em que aparece, funciona como adjetivo, embora seja, na maior parte dos casos, um nome.","no contexto em que aparece, exerce função sintática de sujeito composto."],"correta":2,"explicacao":"Gabarito: <strong>possui um hiato entre a segunda vogal “u”, na segunda sílaba, e a vogal “a”, na terceira sílaba.</strong>.","temas_relacionados":["fonemas","hiatos","silabas"]},{"id":531,"enunciado":"Conhecer os sons das letras, a pronúncia dos dígrafos e dífonos, dos encontros vocálicos e dos consonantais, dos tritongos, dos ditongos e dos hiatos faz parte da boa Oratória. A única sequência que apresenta CORREÇÃO quanto a isso é:","opcoes":["A palavra “subsídio” possui o som de /zê/ no segundo “s”.","As palavras “sintaxe” e “inexorável” possuem a letra “x” com som de /ks/.","As palavras “gratuito”, “fortuito” e “circuito” têm tonicidade no “i”.","As palavras “distinguir”, “extinguir” e “adquirir” não têm o “u” pronunciado.","As palavras como “cruz” e “mas” são pronunciadas com o som /iz/."],"correta":3,"explicacao":"Gabarito: <strong>As palavras “distinguir”, “extinguir” e “adquirir” não têm o “u” pronunciado.</strong>.","banca":"COPESE - UFPI","ano":2020,"temas_relacionados":["fonemas","ditongos","tritongos","hiatos","digrafos","encontrosConsonantais"]},{"id":674,"enunciado":"Para responder à  questão, leia o anúncio a seguir. Nela, um gaúcho em postura de relaxamento e meditação Imagem associada para resolução da questão A palavra \"Gelmax\", nome do medicamento:","opcoes":["Possui mais letras que fonemas.","Possui mais fonemas do que letras, já que a letra \"x\" apresenta mais de um fonema.","É polissílaba","É proparoxítona","Possui um hiato"],"correta":1,"explicacao":"Gabarito: <strong>Possui mais fonemas do que letras, já que a letra \"x\" apresenta mais de um fonema.</strong>.","banca":"Quadrix","ano":2013,"temas_relacionados":["fonemas"]},{"id":680,"enunciado":"Sob a análise acústica do vocábulo arranhãozinho, temos:","opcoes":["dez fonemas;","onze fonemas;","doze fonemas;","dois dígrafos;","um hiato"],"correta":0,"explicacao":"Gabarito: <strong>dez fonemas;</strong>.","banca":"INAZ do Pará","ano":2014,"temas_relacionados":["fonemas"]},{"id":726,"enunciado":"Considerando a relação entre letras e fonemas de palavras do texto, é INCORRETO afirmar que:","opcoes":["A palavra habita possui 5 fonemas e 1 dígrafo.","A palavra entrada possui 6 fonemas e 1 dígrafo.","A palavra escolher possui 7 fonemas e 1 dígrafo.","A palavra lixo possui 4 fonemas e nenhum dígrafo.","A palavra espaço possui 6 fonemas e nenhum dígrafo."],"correta":0,"explicacao":"Gabarito: <strong>A palavra habita possui 5 fonemas e 1 dígrafo.</strong>.","banca":"Instituto Fênix","ano":2026,"temas_relacionados":["fonemas","digrafos"]},{"id":831,"enunciado":"Em termos fonéticos, “presente” e “mundo” são compostos, respectivamente, por:","opcoes":["8 fonemas; 5 fonemas.","7 fonemas e 1 dígrafo; 5 fonemas.","8 fonemas; 4 fonemas e 1 dígrafo.","6 fonemas e 2 dígrafos; 4 fonemas e 1 dígrafo.","7 fonemas e 1 dígrafo; 4 fonemas e 1 dígrafo."],"correta":4,"explicacao":"Gabarito: <strong>7 fonemas e 1 dígrafo; 4 fonemas e 1 dígrafo.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["fonemas","digrafos"]},{"id":841,"enunciado":"Julgue o item a seguir.\nSegundo o novo Acordo Ortográfico da Língua Portuguesa, as sucessões de mais de duas consoantes ou de m ou n, com o valor de nasalidade, e duas ou mais consoantes são divisíveis por um de dois meios: se nelas entra um dos grupos que são indivisíveis (de acordo com o preceito 1º), esse grupo forma sílaba para diante, ficando a consoante ou consoantes que o precedem ligadas à sílaba anterior; se nelas não entra nenhum desses grupos, a divisão dá-se sempre antes da última consoante.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["fonemas","silabas","ortografia"]},{"id":963,"enunciado":"As palavras podem estabelecer diversas formas de associação. Quando essa relação se dá por meio do sentido, constitui-se um campo semântico. Nesse caso, não se trata de sinônimos ou antônimos, mas de uma proximidade de significado dentro de determinado contexto. Com base nisso, analise as afirmativas a seguir: I.A polissemia ocorre quando uma mesma forma apresenta mais de um significado, cada um pertencente a diferentes campos semânticos. Assim, não se deve entender a polissemia como imprecisão de sentido, pois cada significado é definido e específico. Um exemplo é o verbo 'andar', que possui diversos significados na língua portuguesa. II.As palavras 'flor', 'jardim' e 'perfume' constituem campo semântico, pois embora não pertençam a um grupo delimitado, a associação entre elas é evidente. III.A sinonímia ocorre quando duas ou mais palavras têm o significado idêntico ao outro, podendo ser utilizada uma em substituição da outra, sem que haja alteração de sentido, independentemente do contexto. IV.A homonímia é a propriedade de duas ou mais formas, inteiramente distintas pela significação ou função, terem a mesma estrutura fonológica, os mesmos fonemas, dispostos na mesma ordem e subordinados ao mesmo tipo de acentuação. É correto o que se afirma em:","opcoes":["II e III, apenas.","I, II, III e IV.","I e IV, apenas.","I, II e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1450,"enunciado":"Considere a frase extraída do texto e analise as assertivas a seguir, à luz dos conhecimentos de sintaxe e fonética da Língua Portuguesa: A medida representa um marco histórico e coloca o RS como projeto-piloto da iniciativa no Brasil. I. O vocábulo histórico apresenta correspondência exata entre o número de letras e o número de fonemas. II. As formas verbais representa e coloca encontram-se conjugadas no presente do indicativo. III. O segmento um marco histórico exerce a função de objeto indireto do verbo representa. Está CORRETO o que se afirma em:","opcoes":["II, apenas.","II e III, apenas.","I e II, apenas.","I, II е III."],"correta":0,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["fonemas"]},{"id":1451,"enunciado":"Relacione a coluna B de acordo com a coluna A. COLUNA A I. Aliteração. II. Manipulação de fonemas. COLUNA B ( ) “No trio ‘bola, boca, casa’, diga quais duas palavras começam com o mesmo som.” ( ) “Diga ‘pato’; agora troque o som /p/ por /g/ e fale a nova palavra.” ( ) “Diga ‘faca’; agora fale de novo sem o som /f/ do começo.” ( ) “Vou falar ‘fita, faca, mala’; diga quais duas começam com o mesmo som.” Marque a opção que apresenta a sequência CORRETA.","opcoes":["II – I – II – I.","II – II – I – I.","I – II – II – I.","II – I – I – II.","II – II – II – I."],"correta":2,"explicacao":"Gabarito: <strong>I – II – II – I.</strong>.","banca":"Fundação CETREDE","ano":2026,"temas_relacionados":["fonemas"]},{"id":1455,"enunciado":"Considerando o desenvolvimento da linguagem, analisar os itens. I. A fala pré-linguística é a produção de sons que não são palavras, como choro, balbucio e imitação acidental e deliberada de sons sem compreensão de seu significado. II. Os bebês primeiro se familiarizam com os sons das palavras e locuções e, mais tarde, atribuem significados a elas. III. Os bebês não conseguem reconhecer sons básicos (fonemas) de sua língua nativa aos 6 meses. Está CORRETO o que se afirma:","opcoes":["Apenas no item I.","Apenas no item II.","Apenas nos itens I e II.","Apenas nos itens II e III"],"correta":2,"explicacao":"Gabarito: <strong>Apenas nos itens I e II.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["fonemas"]},{"id":1456,"enunciado":"\"Em 2025, a prova voltou a valer como certificado de conclusão da educação básica para quem não terminou a escola, como o Diogo. Mas o Inep, órgão do Ministério da Educação responsável pelo Enem, ainda não emitiu o documento que ele precisa para se matricular na faculdade de Psicologia. O medo é de perder a vaga.\" Com base na fonética e na fonologia, complete as lacunas dos enunciados a seguir: I.O vocábulo___apresenta encontro consonantal, dígrafo vocálico e encontro vocálico. II.O vocábulo ___ apresenta dígrafo consonantal, pois duas letras representam o som de uma única consoante. III.O vocábulo___ apresenta o mesmo número de letras e fonemas, uma vez que todas as letras são pronunciadas. IV.O vocábulo___apresenta mais letras do que fonemas. A sequência que completa as lacunas correta e respectivamente","opcoes":["Órgão, quem, documento, ainda.","Educação, que, ainda, Psicologia.","Órgão, que, matricular, precisa.","Conclusão, quem, certificado, documento","Ministério, terminou, como, escola."],"correta":3,"explicacao":"Gabarito: <strong>Conclusão, quem, certificado, documento</strong>.","banca":"AMAUC","ano":2026,"temas_relacionados":["fonemas","digrafos","encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":1458,"enunciado":"Assinale a única alternativa abaixo que apresenta uma vogal. A)","opcoes":["Ç","W","U","J"],"correta":2,"explicacao":"Gabarito: <strong>U</strong>.","banca":"Instituto IACP","ano":2026,"temas_relacionados":["fonemas"]},{"id":1463,"enunciado":"Considerando a relação entre letras (grafemas) e fonemas (sons), analise as palavras \"crescer\" e \"florescer\". Quantas letras e fonemas essas palavras apresentam, respectivamente?","opcoes":["6 letras e 7 fonemas; 8 letras e 9 fonemas.","7 letras e 7 fonemas; 9 letras e 9 fonemas.","7 letras e 6 fonemas; 9 letras e 8 fonemas.","7 letras e 5 fonemas; 9 letras e 7 fonemas.","6 letras e 6 fonemas; 8 letras e 8 fonemas."],"correta":2,"explicacao":"Gabarito: <strong>7 letras e 6 fonemas; 9 letras e 8 fonemas.</strong>.","banca":"FAFIPA","ano":2025,"temas_relacionados":["fonemas"]},{"id":1464,"enunciado":"Assinale a alternativa que apresenta uma palavra em que o número de letras NÃO equivale ao número de fonemas.","opcoes":["Gato.","Chuva.","Casa.","Tigre.","Mapa."],"correta":1,"explicacao":"Gabarito: <strong>Chuva.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1466,"enunciado":"Assinale a alternativa incorreta quanto à classificação das vogais na língua portuguesa.","opcoes":["As vogais são classificadas quanto à zona de articulação.","As vogais são classificadas quanto à intensidade.","As vogais são classificadas quanto ao timbre.","As vogais são classificadas quanto ao papel das cavidades bucal e nasal.","As vogais são classificadas quanto à representação gráfica."],"correta":4,"explicacao":"Gabarito: <strong>As vogais são classificadas quanto à representação gráfica.</strong>.","banca":"Avança SP","ano":2023,"temas_relacionados":["fonemas"]},{"id":1467,"enunciado":"Escolha e marque com X a palavra que contém o MAIOR número de letras:","opcoes":["Setembro;","Amarelo;","Prevenção;","Suicídio."],"correta":2,"explicacao":"Gabarito: <strong>Prevenção;</strong>.","banca":"Máxima","ano":2023,"temas_relacionados":["fonemas"]},{"id":1468,"enunciado":"Escolha e marque com X a palavra que contém o MENOR número de letras:","opcoes":["Setembro","Amarelo","Prevenção","Suicídio"],"correta":1,"explicacao":"Gabarito: <strong>Amarelo</strong>.","banca":"Máxima","ano":2023,"temas_relacionados":["fonemas"]},{"id":1469,"enunciado":"No contexto do Modelo de Resposta à Intervenção (RTI) e da instrução grafofonêmica, avalie as situações a seguir e identifique em qual delas a correspondência entre letras (grafemas) e sons (fonemas) é mais previsível, baseando-se na posição da letra dentro da palavra:","opcoes":["A letra 'h' em palavras onde não corresponde a nenhum som fonético.","A letra 'l' em final de sílaba em palavras como 'Brasil', onde assume o som de /u/, contrastando com o som de /l/ em outros contextos.","A letra 'x' em palavras como 'caixa', 'próximo', 'táxi' e 'exemplo', onde ocorre entre vogais.","A letra 'c' em diferentes palavras, onde pode ter o som de /s/ como em 'cena' ou o som de /k/ como em 'casa'."],"correta":1,"explicacao":"Gabarito: <strong>A letra 'l' em final de sílaba em palavras como 'Brasil', onde assume o som de /u/, contrastando com o som de /l/ em outros contextos.</strong>.","banca":"IDCAP","ano":2023,"temas_relacionados":["fonemas","silabas"]},{"id":1470,"enunciado":"Levando-se em consideração os princípios ortoépicos, em qual trecho existe consoante constritivo-fricativo-palatal-surda?","opcoes":["“‘[...] achais que uma criança que chegou assim aos quinze anos tenha perdido os anos precedentes?’” (l. 20 e 21).","“Aqui o educando deverá aprender a discernir entre o bem e o mal, o certo e o errado” (l. 03 e 04).","“Rousseau nos apresenta um processo formativo para seu aluno fictício Emílio” (l. 01).","“O que o genebrino almeja é um aluno que possua um coração bom” (l. 16)."],"correta":0,"explicacao":"Gabarito: <strong>“‘[...] achais que uma criança que chegou assim aos quinze anos tenha perdido os anos precedentes?’” (l. 20 e 21).</strong>.","banca":"IMPARH","ano":2025,"temas_relacionados":["fonemas"]},{"id":1471,"enunciado":"Assinale a alternativa cuja letra c da palavra NÃO represente o mesmo fonema representado pela letra c na palavra cidade:","opcoes":["Parece.","Você.","Percebem.","Busca.","Certos."],"correta":3,"explicacao":"Gabarito: <strong>Busca.</strong>.","banca":"FAU","ano":2023,"temas_relacionados":["fonemas"]},{"id":1472,"enunciado":"Na fonologia, a combinação de sons no interior de uma palavra é conhecida como:","opcoes":["morfologia.","sintaxe.","fonotática.","fonética."],"correta":2,"explicacao":"Gabarito: <strong>fonotática.</strong>.","banca":"Gama Consult","ano":2023,"temas_relacionados":["fonemas"]},{"id":1474,"enunciado":"A respeito do número de fonemas de palavras do texto, é possível concluir que possuem, respectivamente, 7 e 9 fonemas:","opcoes":["“Amarela” e “conquista”.","“Registros” e “Amarelinha”.","“Conquista” e “Amarelinha”.","“Camisas” e “Garrincha”."],"correta":2,"explicacao":"Gabarito: <strong>“Conquista” e “Amarelinha”.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["fonemas"]},{"id":1476,"enunciado":"Assinale a alternativa cuja letra c da palavra NÃO represente o mesmo fonema representado pela letra c na palavra cidade:","opcoes":["Central.","Franceses.","Século.","Celebrado.","Notícia."],"correta":2,"explicacao":"Gabarito: <strong>Século.</strong>.","banca":"FAU","ano":2025,"temas_relacionados":["fonemas"]},{"id":1479,"enunciado":"Assinale a alternativa cuja letra em destaque NÃO represente o mesmo fonema representado pela letra s na palavra visitantes:","opcoes":["Zona.","Localizado.","Caso.","Desaparecido.","Serpente."],"correta":4,"explicacao":"Gabarito: <strong>Serpente.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["fonemas"]},{"id":1480,"enunciado":"Quantas letras e fonemas possui a palavra “depressão”?","opcoes":["9 letras e 9 fonemas.","8 letras e 9 fonemas.","9 letras e 8 fonemas.","8 letras e 8 fonemas."],"correta":2,"explicacao":"Gabarito: <strong>9 letras e 8 fonemas.</strong>.","banca":"Itame","ano":2023,"temas_relacionados":["fonemas"]},{"id":1486,"enunciado":"Qual alternativa apresenta uma palavra do texto composta por doze fonemas?","opcoes":["Transferidos.","Desintoxicar.","Simplesmente.","Desintoxicação."],"correta":1,"explicacao":"Gabarito: <strong>Desintoxicar.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["fonemas"]},{"id":1487,"enunciado":"A palavra “oxigênio” apresenta determinado som para “x”. Com isso em mente, assinalar a alternativa em que a palavra também apresenta este mesmo som para “x”:","opcoes":["Xadrez.","Flexível.","Pretexto.","Exame."],"correta":1,"explicacao":"Gabarito: <strong>Flexível.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["fonemas"]},{"id":1490,"enunciado":"“Às vezes no silêncio da noite, eu fico imaginado nós dois [...]” Assinale a alternativa na qual a palavra apresenta o mesmo número de letras e fonemas que “silêncio”.","opcoes":["Hospital.","Cuidado.","Sofrido.","Companheiro","Gramado."],"correta":0,"explicacao":"Gabarito: <strong>Hospital.</strong>.","banca":"LJ Assessoria e Planejamento Administrativo Limita","ano":2024,"temas_relacionados":["fonemas"]},{"id":1491,"enunciado":"A palavra “coisa” é escrita com S e tem som de Z. Assinale a alternativa em que ocorre o mesmo caso.","opcoes":["Bele_a.","Bol_a.","A_ulejo.","Aten_iosa.","Pre_o."],"correta":4,"explicacao":"Gabarito: <strong>Pre_o.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1492,"enunciado":"Qual das palavras abaixo apresenta o mesmo número de letras e fonemas?","opcoes":["Aplicativos.","Pessoais.","Carro.","Espelhos.","Cadeirinha."],"correta":0,"explicacao":"Gabarito: <strong>Aplicativos.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1493,"enunciado":"Qual alternativa que apresenta a quantidade de vogais e consoantes da palavra “desrespeitado”?","opcoes":["6 consoantes e 6 vogais.","5 consoantes e 6 vogais.","6 consoantes e 7 vogais.","7 consoantes e 6 vogais."],"correta":3,"explicacao":"Gabarito: <strong>7 consoantes e 6 vogais.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["fonemas"]},{"id":1494,"enunciado":"A palavra \"CALMAMENTE\" possui quantos fonemas?","opcoes":["9 fonemas.","8 fonemas.","10 fonemas.","4 fonemas.","7 fonemas."],"correta":0,"explicacao":"Gabarito: <strong>9 fonemas.</strong>.","banca":"Instituto Ágata","ano":2024,"temas_relacionados":["fonemas"]},{"id":1496,"enunciado":"Em relação a termos retirados do texto, analise as assertivas a seguir: I. Nas palavras “experiência” e “explicação”, o “x” tem som de “s”. II. Na palavra “relaxamento”, o “x” tem som de “ch”. III. Na palavra “existem”, o “x” tem som de “z”. Quais estão corretas?","opcoes":["Apenas I.","Apenas III.","Apenas I e II.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1497,"enunciado":"Em se tratando de fonemas, as palavras “táxi” e “carrossel” possuem, respectivamente:","opcoes":["5 e 7 fonemas.","4 e 9 fonemas.","5 e 9 fonemas.","4 e 7 fonemas."],"correta":0,"explicacao":"Gabarito: <strong>5 e 7 fonemas.</strong>.","banca":"ADM&TEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1499,"enunciado":"Considerar o número de fonemas das palavras abaixo e analisar os itens. I. Queijo: 6 fonemas. II. Carro: 4 fonemas. III. Ventilador: 9 fonemas. Está CORRETO o que se afirma:","opcoes":["Apenas no item I.","Apenas no item II.","Apenas nos itens I e III.","Apenas nos itens II e III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas nos itens II e III.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["fonemas"]},{"id":1500,"enunciado":"Qual é o fonema representado pela letra \"ç\" no trecho \"o que diz aí na da relação dos desmatamentos com a falta de água?\"","opcoes":["/s/","/z/","/ʃ/","/tʃ/"],"correta":0,"explicacao":"Gabarito: <strong>/s/</strong>.","banca":"IDEP Brasil","ano":2025,"temas_relacionados":["fonemas"]},{"id":1503,"enunciado":"Marque com um X a palavra que NÃO contém consoante.","opcoes":["atlas;","iglu;","ioiô;","pião."],"correta":2,"explicacao":"Gabarito: <strong>ioiô;</strong>.","banca":"Máxima","ano":2025,"temas_relacionados":["fonemas"]},{"id":1506,"enunciado":"Escolha e marque com X a alternativa que só contém letras:","opcoes":["A, B, C, D;","1, 2, 3, 4;","A, 2, B, @;","B, ?, 8, §."],"correta":0,"explicacao":"Gabarito: <strong>A, B, C, D;</strong>.","banca":"Máxima","ano":2025,"temas_relacionados":["fonemas"]},{"id":1507,"enunciado":"Escolha e marque com X a palavra que contém o MAIOR número de letras:","opcoes":["Norte;","Município;","Área;","Itambacuri."],"correta":3,"explicacao":"Gabarito: <strong>Itambacuri.</strong>.","banca":"Máxima","ano":2025,"temas_relacionados":["fonemas"]},{"id":1508,"enunciado":"Escolha e marque com X a palavra que contém o MENOR número de letras:","opcoes":["Norte;","Área;","Município;","Itambacuri."],"correta":1,"explicacao":"Gabarito: <strong>Área;</strong>.","banca":"Máxima","ano":2025,"temas_relacionados":["fonemas"]},{"id":1509,"enunciado":"As vogais que estão presentes na palavra GERAIS são:","opcoes":["G – R – S;","GE – RAIS;","E – A – I;","G – E – R – A – I S."],"correta":2,"explicacao":"Gabarito: <strong>E – A – I;</strong>.","banca":"Máxima","ano":2025,"temas_relacionados":["fonemas"]},{"id":1512,"enunciado":"Qual das alternativas apresenta apenas palavras que iniciam com consoante?","opcoes":["Ilha | câmera | porta.","Garrafa | abóbora | toalha.","Boné | armário | orvalho.","Ferro | língua | cobertor."],"correta":3,"explicacao":"Gabarito: <strong>Ferro | língua | cobertor.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["fonemas"]},{"id":1513,"enunciado":"Quantos fonemas há na palavra “excesso”?","opcoes":["6 fonemas.","5 fonemas.","7 fonemas.","4 fonemas."],"correta":1,"explicacao":"Gabarito: <strong>5 fonemas.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["fonemas"]},{"id":1514,"enunciado":"Quantos fonemas (sons da fala relacionados a cada letra) há na palavra “graus”, retirada do texto?","opcoes":["3.","4.","5.","6.","7."],"correta":2,"explicacao":"Gabarito: <strong>5.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1515,"enunciado":"Quantas letras e fonemas tem a palavra “pequenino”?","opcoes":["9 letras e 8 fonemas.","9 letras e 9 fonemas.","8 letras e 8 fonemas.","8 letras e 9 fonemas."],"correta":0,"explicacao":"Gabarito: <strong>9 letras e 8 fonemas.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["fonemas"]},{"id":1516,"enunciado":"Assinale a alternativa que possui 5 letras e 4 fonemas?","opcoes":["Harpa.","Brasa.","Pluma.","Festa."],"correta":0,"explicacao":"Gabarito: <strong>Harpa.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["fonemas"]},{"id":1517,"enunciado":"Quantos fonemas tem a palavra “esportes”?","opcoes":["6.","7.","8.","9.","10."],"correta":2,"explicacao":"Gabarito: <strong>8.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1520,"enunciado":"Assinale a alternativa em que a palavra apresentada tem mais fonemas do que letras.","opcoes":["Aranha.","Inseticida.","Intoxicante.","Preâmbulo.","Desafiador."],"correta":2,"explicacao":"Gabarito: <strong>Intoxicante.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1521,"enunciado":"Assinale a alternativa cuja letra s da palavra NÃO represente o mesmo fonema representado pela letra s na palavra defesa:","opcoes":["Visitantes.","Usado.","Sala.","Presença.","Uso."],"correta":2,"explicacao":"Gabarito: <strong>Sala.</strong>.","banca":"FAU","ano":2025,"temas_relacionados":["fonemas"]},{"id":1524,"enunciado":"Ao analisar a palavra “destino”, retirada do texto, em relação ao número de vogais e consoantes, temos:","opcoes":["4 consoantes e 3 vogais.","3 consoantes e 4 vogais.","6 consoantes e 6 vogais.","3 consoantes e 6 vogais."],"correta":0,"explicacao":"Gabarito: <strong>4 consoantes e 3 vogais.</strong>.","banca":"GANZAROLI","ano":2024,"temas_relacionados":["fonemas"]},{"id":1526,"enunciado":"A língua portuguesa é organizada em pequenas unidades de som que ajudam na pronúncia e na escrita das palavras, facilitando a comunicação. Essas unidades seguem regras que influenciam tanto a forma como falamos quanto como escrevemos. Entender essa divisão é importante para aprender a grafia correta das palavras, a maneira certa de pronunciá-las e até mesmo como elas se encaixam nas frases (CINTRA, 2020). Com base no conceito de sílaba na língua portuguesa, assinale a alternativa correta.","opcoes":["A divisão silábica das palavras em português segue sempre critérios fixos e invariáveis, de modo que uma palavra terá sempre a mesma segmentação em qualquer contexto linguístico.","A sílaba é uma unidade exclusiva da escrita, pois sua divisão depende unicamente das regras ortográficas de hifenização, sem relação com a pronúncia real das palavras.","A sílaba constitui uma unidade fônica formada por um ou mais fonemas articulados em torno de uma vogal, que funciona como seu núcleo imprescindível, podendo vir acompanhada de consoantes em posições marginais.","Toda sílaba da língua portuguesa deve conter obrigatoriamente uma consoante inicial, pois o idioma não admite sílabas constituídas apenas por vogais."],"correta":2,"explicacao":"Gabarito: <strong>A sílaba constitui uma unidade fônica formada por um ou mais fonemas articulados em torno de uma vogal, que funciona como seu núcleo imprescindível, podendo vir acompanhada de consoantes em posições marginais.</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["fonemas","silabas","ortografia"]},{"id":1531,"enunciado":"No fragmento “Se faz tanto tempo a gente não quer nem saber”, a palavra “tempo” é composta por:","opcoes":["duas consoantes e três vogais.","duas vogais e três consoantes.","duas vogais, duas consoantes e uma semivogal.","uma vogal, duas consoantes e uma semivogal.","duas vogais e três semivogais."],"correta":1,"explicacao":"Gabarito: <strong>duas vogais e três consoantes.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["fonemas"]},{"id":1532,"enunciado":"Analise os vocábulos abaixo e assinale a opção em que a há palavras com o mesmo número de letras e de fonemas:","opcoes":["“semana”; “assado “.","“econômico”; “antigamente”.","“olhos”; “bolo”.","“bisavó”; “lembro”.","“cortava”; “Regrava”:"],"correta":4,"explicacao":"Gabarito: <strong>“cortava”; “Regrava”:</strong>.","banca":"CONTEMAX","ano":2024,"temas_relacionados":["fonemas"]},{"id":1536,"enunciado":"Com base nas regras de fonologia e ortografia, quanto à classificação de fonemas e letras, analisar os itens. I. Vermelho: 8 letras e 7 fonemas. II. Fixo: 4 letras e 5 fonemas. III. Carro: 5 letras e 5 fonemas. Está CORRETO o que se afirma:","opcoes":["Apenas nos itens I e II.","Apenas nos itens I e III.","Apenas nos itens II e III.","Em todos os itens."],"correta":0,"explicacao":"Gabarito: <strong>Apenas nos itens I e II.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["fonemas","ortografia"]},{"id":1542,"enunciado":"A fonética e a fonologia, embora frequentemente estudadas juntas, são disciplinas distintas. A fonética estuda os sons como entidades físico-articulatórias isoladas, tendo como unidade o fone. Já a fonologia investiga os sons a partir de um ponto de vista funcional, como elementos que integram um sistema linguístico, e sua unidade é o fonema (Castilho, 2019). Sobre fones e os fonemas, afirma-se que","opcoes":["as realizações concretas dos fones são chamadas de alofones.","o fonema é uma unidade concreta da língua, enquanto o fone tem um caráter abstrato.","o fonema, por si só, não apresenta significado, mas gera distinções de sentido em uma língua.","uma análise dos fonemas de determinada estrutura permitiria analisar as variações linguísticas regionais."],"correta":2,"explicacao":"Gabarito: <strong>o fonema, por si só, não apresenta significado, mas gera distinções de sentido em uma língua.</strong>.","banca":"IF Sul Rio-Grandense","ano":2025,"temas_relacionados":["fonemas"]},{"id":1543,"enunciado":"Sobre a relação entre letras e fonemas e as famílias de palavras, assinale a alternativa correta.","opcoes":["A palavra “pessoa” tem 6 letras e 6 fonemas.","A palavra “pipoca” tem 6 letras e 5 fonemas.","A palavra “musicoterapia” tem 13 letras e 12 fonemas.","As palavras “escrever” e “escrivão” pertencem à mesma família de palavras.","As palavras “amanhecer” e “dormir” pertencem à mesma família de palavras."],"correta":3,"explicacao":"Gabarito: <strong>As palavras “escrever” e “escrivão” pertencem à mesma família de palavras.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1544,"enunciado":"São palavras com o mesmo número de letras e fonemas: I. Andaime. II. Detalhe. III. Letra. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>Apenas III.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1545,"enunciado":"Indique a alternativa que contém uma palavra que possui o mesmo número de letras e de fonemas.","opcoes":["Chuva","Livro","Samba;","Carroça;"],"correta":1,"explicacao":"Gabarito: <strong>Livro</strong>.","banca":"EVO Concursos","ano":2025,"temas_relacionados":["fonemas"]},{"id":1546,"enunciado":"Sobre as palavras \"pessoas\" e \"diferentes\", assinale a alternativa correta em relação ao número de fonemas.","opcoes":["A  palavra  \"pessoas\"  possui  6  fonemas,  enquanto \"diferentes\" possui 9 fonemas.","A  palavra  \"pessoas\"  possui  7  fonemas,  enquanto \"diferentes\" possui 10 fonemas.","A  palavra  \"pessoas\"  possui  7  fonemas,  enquanto \"diferentes\" possui 9 fonemas.","A  palavra  \"pessoas\"  possui  6  fonemas,  enquanto \"diferentes\" possui 10 fonemas."],"correta":0,"explicacao":"Gabarito: <strong>A  palavra  \"pessoas\"  possui  6  fonemas,  enquanto \"diferentes\" possui 9 fonemas.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["fonemas"]},{"id":1547,"enunciado":"A palavra “milho” tem:","opcoes":["1 vogal e 4 consoantes.","2 vogais e 3 consoantes.","3 vogais e 2 consoantes.","4 vogais e 1 consoante.","5 vogais e nenhuma consoante."],"correta":1,"explicacao":"Gabarito: <strong>2 vogais e 3 consoantes.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1548,"enunciado":"Considerando a relação entre letras e sons, assinale a alternativa que indica corretamente o número de fonemas das palavras “sexo” e “pacientes”.","opcoes":["“sexo” possui 4 fonemas e “pacientes” possui 8 fonemas.","“sexo” possui 5 fonemas e “pacientes” possui 9 fonemas.","“sexo” possui 4 fonemas e “pacientes” possui 9 fonemas.","“sexo” possui 5 fonemas e “pacientes” possui 8 fonemas."],"correta":3,"explicacao":"Gabarito: <strong>“sexo” possui 5 fonemas e “pacientes” possui 8 fonemas.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["fonemas"]},{"id":1549,"enunciado":"Sobre as palavras \"pessoas\" e \"diferentes\", assinale a alternativa correta em relação ao número de fonemas.","opcoes":["A palavra \"pessoas\" possui 6 fonemas, enquanto \"diferentes\" possui 9 fonemas.","A palavra \"pessoas\" possui 7 fonemas, enquanto \"diferentes\" possui 10 fonemas.","A palavra \"pessoas\" possui 7 fonemas, enquanto \"diferentes\" possui 9 fonemas","A palavra \"pessoas\" possui 6 fonemas, enquanto \"diferentes\" possui 10 fonemas."],"correta":0,"explicacao":"Gabarito: <strong>A palavra \"pessoas\" possui 6 fonemas, enquanto \"diferentes\" possui 9 fonemas.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["fonemas"]},{"id":1550,"enunciado":"Quantas vogais há na palavra “estimulando”?","opcoes":["3.","4.","5.","6.","7."],"correta":2,"explicacao":"Gabarito: <strong>5.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1551,"enunciado":"Quantas consoantes há na palavra “promovendo”?","opcoes":["3.","4.","5.","6.","7."],"correta":3,"explicacao":"Gabarito: <strong>6.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1555,"enunciado":"Quantas consoantes existem na palavra “cultivado”?","opcoes":["2.","3.","4.","5."],"correta":3,"explicacao":"Gabarito: <strong>5.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1556,"enunciado":"Quantas vogais existem na palavra “problema”?","opcoes":["1.","2.","3.","4."],"correta":2,"explicacao":"Gabarito: <strong>3.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1557,"enunciado":"Quantas consoantes existem na palavra “alimentos”?","opcoes":["3.","4.","5.","6."],"correta":2,"explicacao":"Gabarito: <strong>5.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1558,"enunciado":"Quantas vogais existem na palavra “consumidas”?","opcoes":["3.","4.","5.","6."],"correta":1,"explicacao":"Gabarito: <strong>4.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["fonemas"]},{"id":1559,"enunciado":"Em relação ao número de letras e fonemas, pode-se afirmar que “pensando” possui:","opcoes":["Duas letras a mais que o número de fonemas.","Uma letra a mais que o número de fonemas","Três letras a mais que o número de fonemas.","O mesmo número de fonemas e letras."],"correta":0,"explicacao":"Gabarito: <strong>Duas letras a mais que o número de fonemas.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["fonemas"]},{"id":1561,"enunciado":"A professora Lúcia quer desenvolver a consciência fonológica de seus alunos. Qual atividade ajudaria os alunos a reconhecerem que as palavras são compostas por diferentes sons?","opcoes":["Uma competição de soletração entre os alunos, incentivando o aprendizado coletivo.","Um questionário sobre o significado de palavras novas.","Um exercício onde os alunos identificam e classificam palavras com base nos sons iniciais, médios e finais.","Uma atividade de leitura coletiva em sala de aula.","Uma atividade de escrita criativa onde os alunos escrevem pequenas histórias, e depois leem para os demais."],"correta":2,"explicacao":"Gabarito: <strong>Um exercício onde os alunos identificam e classificam palavras com base nos sons iniciais, médios e finais.</strong>.","banca":"Unesc","ano":2024,"temas_relacionados":["fonemas"]},{"id":1563,"enunciado":"Na palavra \"mudanças\", o número total de fonemas é:","opcoes":["8 fonemas, correspondendo a todas as letras.","7 fonemas, devido à presença de um dígrafo.","6 fonemas, por causa do encontro vocálico.","9 fonemas, incluindo os dígrafos."],"correta":1,"explicacao":"Gabarito: <strong>7 fonemas, devido à presença de um dígrafo.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["fonemas","digrafos"]},{"id":1564,"enunciado":"Qual alternativa apresenta uma palavra do texto que possui, na sua totalidade, 9 fonemas?","opcoes":["pouquinho.","panturrilhas.","alimentos.","adoçantes."],"correta":1,"explicacao":"Gabarito: <strong>panturrilhas.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["fonemas"]},{"id":1565,"enunciado":"Com base na análise fonológica, assinale a alternativa que apresenta corretamente o número de fonemas das palavras \"quantidade\", \"levantamento\" e \"queda\".","opcoes":["Quantidade: 10 fonemas; levantamento: 12 fonemas; queda: 4 fonemas.","Quantidade: 9 fonemas; levantamento: 11 fonemas; queda: 5 fonemas.","Quantidade: 10 fonemas; levantamento: 11 fonemas; queda: 5 fonemas.","Quantidade: 9 fonemas; levantamento: 10 fonemas; queda: 4 fonemas."],"correta":3,"explicacao":"Gabarito: <strong>Quantidade: 9 fonemas; levantamento: 10 fonemas; queda: 4 fonemas.</strong>.","banca":"IDESG","ano":2025,"temas_relacionados":["fonemas"]},{"id":1566,"enunciado":"Fonologia é o ramo da linguística que estuda os fonemas, as menores unidades sonoras da língua, e sua relação com as letras (grafemas). Enquanto os fonemas representam sons, as letras são sua representação gráfica, podendo haver diferenças entre o som produzido e a escrita (Cagliari, 2007). Assinale a alternativa correta quanto ao número de letras e fonemas dos vocábulos apresentados.","opcoes":["Enxame = sete letras e cinco fonemas.","Champanhe = nove letras e oito fonemas.","Chuveiro = oito letras e sete fonemas.","Acesso = seis letras e quatro fonemas."],"correta":2,"explicacao":"Gabarito: <strong>Chuveiro = oito letras e sete fonemas.</strong>.","banca":"Unesc","ano":2025,"temas_relacionados":["fonemas"]},{"id":1568,"enunciado":"A palavra cujo número de letras corresponde à quantidade de fonemas é:","opcoes":["aborrecer.","chateado.","singelo.","sucedida."],"correta":3,"explicacao":"Gabarito: <strong>sucedida.</strong>.","banca":"FAFIPA","ano":2024,"temas_relacionados":["fonemas"]},{"id":1569,"enunciado":"Assinale a alternativa em que apresenta, respectivamente, por quantas letras e por quantos fonemas são compostas as palavras \"competência\" e \"retratação\".","opcoes":["11 letras e 9 fonemas; 10 letras e 8 fonemas.","11 letras e 10 fonemas; 10 letras e 9 fonemas.","11 letras e 11 fonemas; 10 letras e 10 fonemas.","11 letras e 9 fonemas; 10 letras e 10 fonemas."],"correta":3,"explicacao":"Gabarito: <strong>11 letras e 9 fonemas; 10 letras e 10 fonemas.</strong>.","banca":"FAFIPA","ano":2024,"temas_relacionados":["fonemas"]},{"id":1571,"enunciado":"No que se refere à pontuação e ortografia no texto 19A1, bem como a aspectos fonológicos de vocábulos nele empregados, julgue o item que se segue.\nIdentificam-se no vocábulo “lexicais” oito letras e oito fonemas.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["fonemas","ortografia"]},{"id":1572,"enunciado":"No que se refere à pontuação e ortografia no texto 19A1, bem como a aspectos fonológicos de vocábulos nele empregados, julgue o item que se segue.\nO vocábulo “histórico” tem nove letras e oito fonemas.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["fonemas","ortografia"]},{"id":1573,"enunciado":"No que se refere à pontuação e ortografia no texto 19A1, bem como a aspectos fonológicos de vocábulos nele empregados, julgue o item que se segue.\nEm cada um dos seguintes vocábulos, o número de letras coincide com o de fonemas: “manuais”; “falantes”; “cognitivo”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["fonemas","ortografia"]},{"id":1576,"enunciado":"Considerando os sentidos e aspectos linguísticos do texto 9A1, julgue o item seguinte.\nNos vocábulos “que”, “processo” e “adaptação”, identificam-se grupos de duas letras que representam um só fonema.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2025,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":1586,"enunciado":"A palavra “envelhecimento” contém:","opcoes":["6 vogais e 8 consoantes.","7 vogais e 7 consoantes.","8 vogais e 6 consoantes.","9 vogais e 5 consoantes.","10 vogais e 4 consoantes."],"correta":0,"explicacao":"Gabarito: <strong>6 vogais e 8 consoantes.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1588,"enunciado":"Qual palavra a seguir NÃO apresenta número correspondente de letras e fonemas?","opcoes":["Culto.","Flores.","Ovos.","Finados.","Homenagem."],"correta":4,"explicacao":"Gabarito: <strong>Homenagem.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1589,"enunciado":"O sistema fonológico do português brasileiro possui uma relação complexa com a ortografia, apresentando algumas particularidades entre a forma escrita e os sons produzidos. Sobre o sistema fonológico e a ortografia vigente da língua portuguesa, assinale a alternativa correta:","opcoes":["A ortografia atual permite que a letra \"c\" seja usada apenas antes das vogais \"a\", \"o\" e \"u\" para representar o som de /k/, enquanto para representar o mesmo som antes das vogais \"e\" e \"i\", utiliza-se exclusivamente a letra \"q\".","O Acordo Ortográfico de 1990 eliminou o uso do trema sobre a letra \"u\" em todos os contextos, mas manteve sua utilização nas palavras de origem estrangeira para manter a pronúncia original.","A letra \"x\" pode representar diferentes fonemas, como em \"exemplo\" (/z/) e \"táxi\" (/ks/), o que exemplifica uma das complexidades do sistema fonológico e ortográfico da língua portuguesa.","No português brasileiro, todos os fonemas possuem uma representação ortográfica única e invariável, garantindo que cada som corresponda a uma única grafia."],"correta":2,"explicacao":"Gabarito: <strong>A letra \"x\" pode representar diferentes fonemas, como em \"exemplo\" (/z/) e \"táxi\" (/ks/), o que exemplifica uma das complexidades do sistema fonológico e ortográfico da língua portuguesa.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["fonemas","ortografia"]},{"id":1594,"enunciado":"A Fonologia é a área da gramática encarregada de estudar como se comportam os sons em uma língua. Sabendo-se disso, assinale a alternativa que informa corretamente a quantidade exata de fonemas de sua respectiva palavra.","opcoes":["processo – apresenta 8 fonemas.","organização – apresenta 10 fonemas.","meteorológica – apresenta 14 fonemas.","industrialização – apresenta 15 fonemas."],"correta":3,"explicacao":"Gabarito: <strong>industrialização – apresenta 15 fonemas.</strong>.","banca":"Instituto Darwin","ano":2024,"temas_relacionados":["fonemas"]},{"id":1607,"enunciado":"Com relação ao número de fonemas de vocábulos do texto, assinale a alternativa INCORRETA.","opcoes":["pessoas possui 6 fonemas.","tempo possui 4 fonemas.","senso possui 4 fonemas.","gentileza possui 8 fonemas.","humanidade possui 10 fonemas."],"correta":4,"explicacao":"Gabarito: <strong>humanidade possui 10 fonemas.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["fonemas"]},{"id":1609,"enunciado":"Em qual das palavras abaixo a letra “s” tem som de “z”?","opcoes":["Lagosta.","Mesário.","Passado.","Pensador.","Buscar."],"correta":1,"explicacao":"Gabarito: <strong>Mesário.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1612,"enunciado":"Imagem associada para resolução da questão Na gramática, cabe à fonética e à fonologia estudar esses sons da fala. Acerca dessa temática é INCORRETO afirmar que:","opcoes":["Fonema é a menor unidade sonora da palavra e tendo significado de acordo com a unidade silábica constituída. São classificados em vogais (orais e nasais), semivogais e consoantes, conforme o modo de produção no aparelho fonador.","A fonética estuda o aspecto físico dos sons da fala, ou seja, estuda a produção e recepção desses sons. Logo, o seu principal objeto de estudo é o aparelho fonador.","A fonologia estuda as funções dos fonemas na língua. Isto é, ocupa-se com a capacidade de combinação e distinção desses fonemas.","Os fonemas são representados na escrita pelas letras do alfabeto. Mas como essa representação não consegue simbolizar com precisão a pronúncia real dos fonemas, foi criado o alfabeto fonético.","Fazem parte da fonologia a ortoepia (ou ortoépia), a prosódia, a ortografia, a acentuação, o dígrafo, o dífono, os encontros vocálicos e os encontros consonantais."],"correta":0,"explicacao":"Gabarito: <strong>Fonema é a menor unidade sonora da palavra e tendo significado de acordo com a unidade silábica constituída. São classificados em vogais (orais e nasais), semivogais e consoantes, conforme o modo de produção no aparelho fonador.</strong>.","banca":"AMAUC","ano":2022,"temas_relacionados":["fonemas","digrafos","encontrosConsonantais","ditongos","hiatos","tritongos","ortografia"]},{"id":1614,"enunciado":"Assinale a alternativa incorreta:","opcoes":["A palavra campo possui 5 letras e 4 fonemas.","A palavra táxi possui 4 letras e 5 fonemas.","A palavra chuva possui 5 letras e 4 fonemas.","A palavra harpa possui 5 letras e 5 fonemas."],"correta":3,"explicacao":"Gabarito: <strong>A palavra harpa possui 5 letras e 5 fonemas.</strong>.","banca":"Gama Consult","ano":2024,"temas_relacionados":["fonemas"]},{"id":1615,"enunciado":"Analise os itens abaixo e, a seguir, assinale a alternativa correta: I – A palavra acesso possui 6 letras e 5 fonemas. II – A palavra chute possui 5 letras e 4 fonemas. III – A palavra táxi possui 4 letras e 5 fonemas. Estão corretos:","opcoes":["Apenas I e II.","Apenas II e III.","Apenas I e III.","I, II e III."],"correta":3,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"Gama Consult","ano":2024,"temas_relacionados":["fonemas"]},{"id":1616,"enunciado":"Alegria, Medo, Tristeza, Raiva e Nojinho são personagens que representam as emoções de Riley. Qual deles possui 4 letras e 4 fonemas?","opcoes":["Nojinho.","Alegria.","Raiva.","Medo."],"correta":3,"explicacao":"Gabarito: <strong>Medo.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["fonemas"]},{"id":1617,"enunciado":"Assinalar a alternativa cuja sentença contenha mais fonemas que as demais.","opcoes":["Inexoravelmente, letra e fonema são diferentes.","Hoje, quase sentimos falta de um processo quente.","Fixamente, olhamos aquela questão irremediável.","Tenho plantadas em casa muitas alcachofras."],"correta":0,"explicacao":"Gabarito: <strong>Inexoravelmente, letra e fonema são diferentes.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["fonemas"]},{"id":1618,"enunciado":"Na atividade linguística, o importante para os falantes é o fonema, e não a série de movimentos articulatórios que o determina. Nesse sentido, analise as afirmações que seguem: I. Assim sendo, enquanto a análise fonética se preocupa tão somente com a articulação, a fonêmica atenta somente para o fonema que, reunindo um feixe de traços que o distingue de outro fonema, permite a comunicação linguística. II.  A fonética pode reconhecer, e realmente o faz, diversas realizações para o / t/ da série ta-te-ti-to-tu; a fonêmica não leva em conta as variações (que se chamam alofones), porque delas não tomam conhecimento os falantes de língua portuguesa. III. Um fonema admite uma gama variada de realizações fonéticas que vai até a conservação da integridade do vocábulo: quando isto não ocorre, diz-se que houve mudança de fonema. BECHARA, E. Moderna gramática portuguesa. 37.ed. revista, ampliada e atualizada conforme o novo Acordo Ortográfico. Rio de Janeiro: Nova Fronteira, 2009. (Com adaptações) Está CORRETO o que se afirma em:","opcoes":["I, II e III.","I e III, apenas.","II e III, apenas.","I e II, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"UNIVALI","ano":2024,"temas_relacionados":["fonemas","ortografia"]},{"id":1619,"enunciado":"Fonética e Fonologia são dois ramos da Linguística que estudam os sons da fala, mas cada um com enfoques diferentes. Em relação a essa temática, analise as afirmações que seguem: I. Fonema: É a menor unidade de som que pode diferenciar o significado de palavras em uma língua. Por exemplo, em português, os sons /p/ e /b/ são fonemas diferentes, pois distinguem palavras como \"pato\" e \"bato\". II. A Fonética é abstrata e funcional, lidando com o sistema de sons de uma língua e as regras que determinam como esses sons interagem para transmitir significado. III. A fonologia também estuda as estruturas silábicas, como as sílabas se organizam dentro das palavras, e os padrões de acentuação e entonação que afetam a comunicação. Está CORRETO o que se afirma em:","opcoes":["I e III, apenas.","II e III, apenas.","I, II e III.","I e II, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I e III, apenas.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["fonemas","silabas"]},{"id":1621,"enunciado":"As palavras “caminhar”, “homem” e “dissimulado” possuem, respectivamente,","opcoes":["oito, cinco e onze fonemas","oito, quatro e nove fonemas.","sete, quatro e dez fonemas","sete, três e onze fonemas.","sete, cinco e dez fonemas."],"correta":2,"explicacao":"Gabarito: <strong>sete, quatro e dez fonemas</strong>.","banca":"FGV","ano":2024,"temas_relacionados":["fonemas"]},{"id":1625,"enunciado":"Em qual alternativa ambas as palavras possuem a mesma quantidade de fonemas?","opcoes":["Hora e bola.","Humor e hora.","Carro e velho.","Pássaro e chuva."],"correta":2,"explicacao":"Gabarito: <strong>Carro e velho.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["fonemas"]},{"id":1628,"enunciado":"A fala e a escrita possuem características bem distintas. O falante da Língua Portuguesa muitas vezes acrescenta na oralidade um fonema vocálico em meio a consoantes. Este é o caso de qual das palavras abaixo?","opcoes":["psicólogo","bailarina","elevador","garagem","sustentar"],"correta":0,"explicacao":"Gabarito: <strong>psicólogo</strong>.","banca":"FEPESE","ano":2024,"temas_relacionados":["fonemas"]},{"id":1635,"enunciado":"A palavra “Alemanha” contém:","opcoes":["7 letras e 7 fonemas.","8 letras e 7 fonemas.","8 letras e 9 fonemas.","7 letras e 8 fonemas.","8 letras e 8 fonemas."],"correta":1,"explicacao":"Gabarito: <strong>8 letras e 7 fonemas.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1636,"enunciado":"A alternativa que apresenta a palavra com mesmo número de letras e fonemas é:","opcoes":["Professor.","Orgulhosos.","Universidade.","Mosquito.","Interessante."],"correta":2,"explicacao":"Gabarito: <strong>Universidade.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1637,"enunciado":"Assinale a alternativa que contém 5 fonemas:","opcoes":["Comida.","Liberdade.","Máquina.","Guerra.","Hélice."],"correta":4,"explicacao":"Gabarito: <strong>Hélice.</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["fonemas"]},{"id":1638,"enunciado":"Assinale a alternativa que apresenta corretamente o número de letras e fonemas na palavra indicada.","opcoes":["Chave: 5 letras e 4 fonemas.","Táxi: 4 letras e 4 fonemas.","Quadro: 6 letras e 5 fonemas.","Exame: 5 letras e 4 fonemas.","Geleira: 7 letras e 6 fonemas."],"correta":0,"explicacao":"Gabarito: <strong>Chave: 5 letras e 4 fonemas.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1639,"enunciado":"O Alfabeto Fonético Internacional é usado em comunicações orais para evitar confusões na transmissão de letras e palavras. Analise as afirmativas abaixo sobre o uso do Alfabeto Fonético Internacional e selecione a alternativa correta: 1. A letra \"B\" é representada pelo código fonético \"Bravo\", garantindo clareza em situações onde a comunicação verbal pode ser comprometida (ICAO, 2023). 2. A letra \"N\" é representada pelo código fonético \"November\", sendo amplamente utilizada em comunicações militares e civis (ICAO, 2023). 3. A letra \"S\" é representada pelo código fonético \"Sierra\", uma prática comum em comunicações para garantir que o som \"S\" não seja confundido com outros sons similares (ICAO, 2023). 4. A letra \"X\" é representada pelo código fonético \"Xenon\", devido à similaridade sonora que minimiza a confusão durante a comunicação (ICAO, 2023). 5. A letra \"E\" é representada pelo código fonético \"Echo\", um termo que é fácil de entender mesmo em condições de sinal fraco ou interferência (ICAO, 2023). Alternativas:","opcoes":["Os itens 1, 2 e 4 são verdadeiros.","Apenas os itens 3, 4 e 5 são verdadeiros.","Os itens 1, 3 e 5 são verdadeiros.","Apenas os itens 1, 2 e 5 são verdadeiros.","Os itens 2, 3 e 4 são verdadeiros."],"correta":2,"explicacao":"Gabarito: <strong>Os itens 1, 3 e 5 são verdadeiros.</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["fonemas"]},{"id":1642,"enunciado":"Assinale a alternativa cuja letra c da palavra NÃO represente o mesmo fonema representado pela letra c na palavra cometa:","opcoes":["Recentes.","Décadas.","Risco.","Acordo.","Comparadas."],"correta":0,"explicacao":"Gabarito: <strong>Recentes.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["fonemas"]},{"id":1644,"enunciado":"Assinale a alternativa correta quanto ao número de letras e fonemas:","opcoes":["Sonha: 5 letras, 6 fonemas.","Que: 3 letras, 3 fonemas.","Hein: 4 letras, 2 fonemas.","Máscara: 7 letras, 6 fonemas.","Palhaço: 7 letras, 9 fonemas."],"correta":2,"explicacao":"Gabarito: <strong>Hein: 4 letras, 2 fonemas.</strong>.","banca":"MSConcursos","ano":2012,"temas_relacionados":["fonemas"]},{"id":1648,"enunciado":"Assinale a opção que apresenta a correta relação entre o número de grafemas e o de fonemas, com as respectivas justificativas.","opcoes":["INFORMAÇÃO → O número de fonemas é maior que o número de grafemas, devido à presença de um dífono.","IMPLEMENTAÇÃO → O número de fonemas é menor que o número de grafemas, devido à presença de dois dígrafos vocálicos.","COMUNICAÇÃO → O número de fonemas é menor que o número de letras, devido à presença de dígrafo consonantal.","SEQUÊNCIA → O número de fonemas é maior que o número de letras devido à presença de dois dífonos."],"correta":1,"explicacao":"Gabarito: <strong>IMPLEMENTAÇÃO → O número de fonemas é menor que o número de grafemas, devido à presença de dois dígrafos vocálicos.</strong>.","banca":"UECE-CEV","ano":2023,"temas_relacionados":["fonemas","digrafos"]},{"id":1650,"enunciado":"Indique a opção em que há uma palavra com 6 (seis) fonemas:","opcoes":["Encher.","Tempo.","Xícara.","Objetivo."],"correta":2,"explicacao":"Gabarito: <strong>Xícara.</strong>.","banca":"FAFIPA","ano":2016,"temas_relacionados":["fonemas"]},{"id":1656,"enunciado":"Em relação às normas de ortografia, é correto afirmar que","opcoes":["há sete fonemas na palavra “colheram” (linha 6).","ocorre um hiato na palavra “percentuais” (linha 13).","a palavra “apáticos” (linha 16) é acentuada por ser paroxítona.","a letra destacada na palavra “propensos” (linha 4) representa o fonema [z].","ocorreu um erro no emprego da crase em “mais propensos a serem eleitos” (linhas 11-12)."],"correta":1,"explicacao":"Gabarito: <strong>ocorre um hiato na palavra “percentuais” (linha 13).</strong>.","banca":"FADESP","ano":2011,"temas_relacionados":["fonemas","hiatos","ortografia"]},{"id":1657,"enunciado":"Qual das palavras abaixo tem o mesmo número de letras e fonemas?","opcoes":["Cachorro.","Táxi.","Campo.","Máximo.","Roque."],"correta":3,"explicacao":"Gabarito: <strong>Máximo.</strong>.","banca":"CETREDE","ano":2017,"temas_relacionados":["fonemas"]},{"id":1658,"enunciado":"A palavra abaixo que tem mais vogais que consoantes é:","opcoes":["procurar;","terreiro;","alimento;","galinhas;","adoração."],"correta":4,"explicacao":"Gabarito: <strong>adoração.</strong>.","banca":"FGV","ano":2014,"temas_relacionados":["fonemas"]},{"id":1659,"enunciado":"Na língua portuguesa, a escrita de algumas letras é diferente para o mesmo som, por motivações variadas. Assinale a opção em que a grafia das letras grifadas do par NÃO corresponde à representação do mesmo som.","opcoes":["excepcional – esporte","próximas – coincide","embaixadora – chuteiras","sexismo – França"],"correta":3,"explicacao":"Gabarito: <strong>sexismo – França</strong>.","banca":"UECE-CEV","ano":2019,"temas_relacionados":["fonemas","ortografia"]},{"id":1661,"enunciado":"Na linha 11, aparece a palavra \"distinguem\". É correto afirmar que ela contém","opcoes":["dez fonemas.","nove fonemas.","oito fonemas.","sete fonemas.","seis fonemas."],"correta":3,"explicacao":"Gabarito: <strong>sete fonemas.</strong>.","banca":"IDECAN","ano":2022,"temas_relacionados":["fonemas"]},{"id":1662,"enunciado":"Das palavras abaixo retiradas do texto, assinale aquela que apresenta o mesmo número de letras e de fonemas:","opcoes":["“impressos”.","“frequentemente”.","“armadilhas”.","“misterioso”.","minha”."],"correta":3,"explicacao":"Gabarito: <strong>“misterioso”.</strong>.","banca":"CONTEMAX","ano":2024,"temas_relacionados":["fonemas"]},{"id":1667,"enunciado":"A palavra “hábitos” tem:","opcoes":["7 letras e 7 fonemas.","7 letras e 8 fonemas.","7 letras e 6 fonemas.","7 letras e 5 fonemas.","8 letras e 7 fonemas."],"correta":2,"explicacao":"Gabarito: <strong>7 letras e 6 fonemas.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["fonemas"]},{"id":1668,"enunciado":"O número de vogais e consoantes da palavra “eletrônicos” é:","opcoes":["5 consoantes e 6 vogais.","6 consoantes e 5 vogais.","7 consoantes e 4 vogais.","4 consoantes e 7 vogais.","3 consoantes e 8 vogais."],"correta":1,"explicacao":"Gabarito: <strong>6 consoantes e 5 vogais.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["fonemas"]},{"id":1672,"enunciado":"Com relação a diferença entre fonemas e letras, assinale a alternativa correta.","opcoes":["Fonemas são as letras que escrevemos, enquanto letras são os sons que pronunciamos.","Fonemas são os sons da fala, enquanto letras são os símbolos gráficos que representam esses sons.","Fonemas são usados apenas em línguas faladas, enquanto letras são usadas somente em línguas escritas.","Fonemas e letras são sinônimos e podem ser usados de forma intercambiável."],"correta":1,"explicacao":"Gabarito: <strong>Fonemas são os sons da fala, enquanto letras são os símbolos gráficos que representam esses sons.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["fonemas"]},{"id":1680,"enunciado":"Assinale a alternativa correta acerca das relações entre fonemas e grafias.","opcoes":["A palavra “sol” tem 3 letras e 1 fonema.","A palavra “arara” tem 5 letras e 5 fonemas.","A palavra “táxi” tem 4 letras e 4 fonemas.","Na palavra “triplo” encontramos dois dígrafos.","Na palavra “tranquilo” encontramos um dígrafo."],"correta":1,"explicacao":"Gabarito: <strong>A palavra “arara” tem 5 letras e 5 fonemas.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas","ortografia"]},{"id":1682,"enunciado":"Julgue o item subsequente.\nA análise fonológica dos sons do português pode ser conduzida satisfatoriamente sem a necessidade de considerar as nuances da articulação vocal, uma vez que a correspondência entre letras e sons é direta e inalterada pelas variações contextuais.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":1684,"enunciado":"Julgue o item subsequente.\nA correspondência entre letras e fonemas no português é sempre direta e previsível pode simplificar excessivamente o ensino da ortografia e da leitura.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["fonemas","ortografia"]},{"id":1686,"enunciado":"Julgue o item subsequente.\nA análise fonológica dos fonemas na língua portuguesa requer uma abordagem multidimensional que considere não apenas os aspectos articulatórios e acústicos, mas também as interações suprassegmentais e morfofonêmicas, dada a complexidade das variações sonoras condicionadas por contextos morfológicos e prosódicos.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":1687,"enunciado":"Assinale a alternativa correta em relação ao número de fonemas e de letras das palavras “samba” e “filho”, respectivamente.","opcoes":["5 letras e 4 fonemas – 5 letras e 4 fonemas","5 letras e 5 fonemas – 5 letras e 4 fonemas","5 letras e 4 fonemas – 5 letras e 5 fonemas","5 letras e 3 fonemas – 5 letras e 4 fonemas"],"correta":0,"explicacao":"Gabarito: <strong>5 letras e 4 fonemas – 5 letras e 4 fonemas</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["fonemas"]},{"id":1689,"enunciado":"As palavras abaixo contêm 4 consoantes e 3 vogais, exceto:","opcoes":["recitar","destino","palavras","sedutor","precisa"],"correta":2,"explicacao":"Gabarito: <strong>palavras</strong>.","banca":"IDIB","ano":2023,"temas_relacionados":["fonemas"]},{"id":1690,"enunciado":"Assinale a alternativa que contém palavra com o mesmo número de fonemas que “toxinas”.","opcoes":["Favorece.","Ótimos.","Chás.","Porque.","Fervura."],"correta":0,"explicacao":"Gabarito: <strong>Favorece.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["fonemas"]},{"id":1692,"enunciado":"Quantos fonemas há na palavra ônibus?","opcoes":["2 fonemas.","3 fonemas.","4 fonemas.","5 fonemas.","6 fonemas."],"correta":4,"explicacao":"Gabarito: <strong>6 fonemas.</strong>.","banca":"FACET Concursos","ano":2024,"temas_relacionados":["fonemas"]},{"id":1693,"enunciado":"Imagem associada para resolução da questão A unidade capixaba da CEASA deu nova alternativa aos produtores, comerciantes e consumidores, gerando um novo momento para o mercado hortigranjeiro. Em relação ao número de letras e fonemas da palavra “hortigranjeiro”, assinale a alternativa correta.","opcoes":["15 letras e 14 fonemas.","14 letras e 12 fonemas.","14 letras e 15 fonemas.","14 letras e 13 fonemas.","13 letras e 13 fonemas."],"correta":3,"explicacao":"Gabarito: <strong>14 letras e 13 fonemas.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["fonemas"]},{"id":1694,"enunciado":"A partir do texto abaixo é possível verificar recursos expressivos no plano fônico: REGIME (Millôr Fernandes) Parlamentar, Pra lamentar, Pra ralentar Pra elementar Pra amamentar Pra arrebentar Ou pra militar? (Veja 27/05/81) O texto compõe-se de uma estrofe de sete versos, os dois primeiros tetrassílabos (4 sílabas métricas) e o último pentassílabo (5 sílabas métricas). Com efeito, qual leitura está incorreta.","opcoes":["O quarto verso, tendo em vista as possíveis leituras: prae / le / men / tar ocorre uma sinalefa. Pre / le / men / tar ocorre uma ectlipse. Isto é responsável pela coesão, pois, se por um lado – no eixo vertical – ele se sintoniza com os versos cuja primeira vogal é sempre a, ele também se sintoniza – no eixo horizontal – com a singularidade concernente à natureza formal do vocábulo elementar","Trata-se de um texto de ‘humor’ e os fonemas (vogais e consoantes) atuam na sua estruturação respondendo nesse jogo ao efeito desejado, acumulando-se nos versos os segmentos fônicos mais relevantes para projetar auditivamente a ideia a exprimir","A indagação constitui-se em mais um elemento de coesão do texto e, por conseguinte, de unidade significativa. Essa indagação acionada pela vogal alta no título (Regime) é retomada com uma mudança de entonação (curva ascendente) – característica da frase interrogativa – apenas no último verso (Ou pra militar?)","Regime e militar são termos que se investem de ambiguidade e dinamismo, compondo, assim, o eixo restrição/ampliação","Do primeiro verso para o segundo há a utilização dos mesmos fonemas, embora agrupados diferentemente em vocábulos distintos (com a troca de posição de dois fonemas na primeira sílaba)"],"correta":0,"explicacao":"Gabarito: <strong>O quarto verso, tendo em vista as possíveis leituras: prae / le / men / tar ocorre uma sinalefa. Pre / le / men / tar ocorre uma ectlipse. Isto é responsável pela coesão, pois, se por um lado – no eixo vertical – ele se sintoniza com os versos cuja primeira vogal é sempre a, ele também se sintoniza – no eixo horizontal – com a singularidade concernente à natureza formal do vocábulo elementar</strong>.","banca":"IBFC","ano":2024,"temas_relacionados":["fonemas","silabas"]},{"id":1698,"enunciado":"Na sentença, “imagens sensoriais visuais ao adormecer” (linha 7) a palavra “visuais” apresenta fonema diferente de seu grafema porque o “s”","opcoes":["demonstra o som de “z” ao iniciar com a letra “v”.","representa o som do “s”, como em pessoas.","atribui o som de “ss” ao iniciar com consoante e depois vogal.","assume entre vogais o som de “z”, como em “vicioso”.","é utilizado para indicar que algumas palavras podem ter som de “ç” ou “z”."],"correta":3,"explicacao":"Gabarito: <strong>assume entre vogais o som de “z”, como em “vicioso”.</strong>.","banca":"IDECAN","ano":2024,"temas_relacionados":["fonemas"]},{"id":1699,"enunciado":"O vocábulo abaixo, o qual, mostra mais consoantes que vogais é","opcoes":["pélago.","sublevação.","aguilhoava.","inflexível."],"correta":3,"explicacao":"Gabarito: <strong>inflexível.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["fonemas"]},{"id":1702,"enunciado":"A palavra “televisão” apresenta:","opcoes":["7 vogais e 2 consoantes.","6 vogais e 3 consoantes.","5 vogais e 4 consoantes.","4 vogais e 5 consoantes.","3 vogais e 6 consoantes."],"correta":2,"explicacao":"Gabarito: <strong>5 vogais e 4 consoantes.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":1705,"enunciado":"Em relação ao número de fonemas, pode-se afirmar que “profundidade” possui 2 fonemas a mais que:","opcoes":["Aprisionada.","Suficiente.","Descobrimos.","Equador."],"correta":1,"explicacao":"Gabarito: <strong>Suficiente.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["fonemas"]},{"id":1710,"enunciado":"Considere o vocábulo: “latidinhos”. Marque a alternativa que apresenta o número de letras e de fonemas desse vocábulo:","opcoes":["dez letras e dez fonemas.","dez letras e nove fonemas.","dez letras e oito fonemas.","dez letras e sete fonemas."],"correta":1,"explicacao":"Gabarito: <strong>dez letras e nove fonemas.</strong>.","banca":"Aroeira","ano":2024,"temas_relacionados":["fonemas"]},{"id":1711,"enunciado":"Assinale a alternativa cuja letra g da palavra represente o mesmo fonema representado pela letra g na palavra agência:","opcoes":["Jogos.","Segundo.","Segurança.","Governo.","Estrangeiros."],"correta":4,"explicacao":"Gabarito: <strong>Estrangeiros.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["fonemas"]},{"id":1712,"enunciado":"Assinale a alternativa cuja letra s da palavra represente o mesmo fonema representado pela letra s na palavra série:","opcoes":["Caso.","Observado.","Presente.","Causa.","Presença."],"correta":1,"explicacao":"Gabarito: <strong>Observado.</strong>.","banca":"FAU","ano":2024,"temas_relacionados":["fonemas"]},{"id":1713,"enunciado":"A palavra “espaço” tem 6 letras e _____ fonemas. Assinale a alternativa que preenche corretamente a lacuna do trecho acima.","opcoes":["7.","6.","5.","4.","3."],"correta":1,"explicacao":"Gabarito: <strong>6.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":2001,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir.\nConforme o Acordo Ortográfico da Língua Portuguesa, a palavra “fonoterapia” está grafada corretamente, pois o prefixo “fono” termina em vogal, e o segundo elemento (“terapia”) é iniciado por uma consoante. Por outro lado, na palavra “gastroesofágico”, deveria ser inserido um hífen em razão de o prefixo “gastro” terminar com uma vogal diferente da que inicia o segundo elemento (“esofágico”).\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["fonemas","ortografia","hifen"]},{"id":2003,"enunciado":"“A língua portuguesa é a continuação ininterrupta, no tempo e no espaço, do latim levado à Península Ibérica pela expansão do império romano, no início do séc. III a.C., particularmente no processo de romanização dos povos do oeste e noroeste (lusitanos e galaicos), processo que encontrou tenaz resistência dos habitantes originários dessas regiões.” De acordo com a concepção estruturalista da língua, qual é a unidade básica da análise linguística?","opcoes":["Fonema","Morfema","Palavra","Frase","Texto"],"correta":1,"explicacao":"Gabarito: <strong>Morfema</strong>.","banca":"FUNATEC","ano":2023,"temas_relacionados":["fonemas"]},{"id":2129,"enunciado":"A palavra “desimpedido” (𝓁. 30) é grafada com um “s” porque:","opcoes":["só se escreve “s”, e não “z”, entre duas vogais.","é formada pelo prefixo “-des”, grafado com “s”.","tem um “s” na raiz “–simped”.","é uma forma derivada de impedir."],"correta":1,"explicacao":"Gabarito: <strong>é formada pelo prefixo “-des”, grafado com “s”.</strong>.","banca":"ACEP","ano":2010,"temas_relacionados":["fonemas"]},{"id":2191,"enunciado":"A palavra “desnecessários” (l. 23) tem:","opcoes":["6 consoantes – 8 vogais.","8 consoantes – 6 vogais.","7 consoantes – 7 vogais.","9 consoantes – 5 vogais.","5 consoantes – 9 vogais."],"correta":1,"explicacao":"Gabarito: <strong>8 consoantes – 6 vogais.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["fonemas"]},{"id":2832,"enunciado":"\"Desigualdade social é o principal obstáculo à qualidade da educação no país.\" A separação silábica consiste na divisão das palavras em sílabas, indicada, quando necessário, pelo uso do hífen. Em 'país', por exemplo, a divisão adequada é 'pa-ís'. Com base nas regras de separação silábica e de translineação, analise as afirmativas a seguir e assinale a alternativa incorreta.","opcoes":["A correspondência entre grafemas e fonemas nem sempre é biunívoca: determinadas sequências de letras que representam um único fonema na modalidade oral podem ser distribuídas entre sílabas distintas na escrita.","Na translineação, quando a palavra já possui hífen em sua formação, ele deve ser repetido no início da linha seguinte, a fim de evitar que a separação seja interpretada como mera divisão silábica.","Na translineação, o critério fonético prevalece sobre o gráfico quando se trata de vogais idênticas pronunciadas continuamente, de modo que essas vogais permanecem reunidas na mesma sílaba, por não haver pausa perceptível entre elas na cadeia sonora.","Nos vocábulos formados pelo prefixo 'sub-' seguido de vogal, prevalece a regra silábica geral sobre o critério morfológico, de modo que a consoante b se agrupa à vogal subsequente, como se observa em 'su.ben.ten.der'."],"correta":2,"explicacao":"Gabarito: <strong>Na translineação, o critério fonético prevalece sobre o gráfico quando se trata de vogais idênticas pronunciadas continuamente, de modo que essas vogais permanecem reunidas na mesma sílaba, por não haver pausa perceptível entre elas na cadeia sonora.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["fonemas","silabas","hifen"]},{"id":2837,"enunciado":"O Acordo Ortográfico da Língua Portuguesa de 1990 foi um projeto elaborado pelos países lusófonos com o objetivo de unificar a ortografia do português. Até então, Brasil e Portugal (além dos demais países africanos de língua portuguesa) seguiam regras diferentes de escrita, o que dificultava a produção editorial comum, a circulação de textos, o ensino e a padronização internacional da língua. O acordo foi assinado em 1990 pelos países membros da CPLP, mas enfrentou longos anos de debates e revisões até entrar efetivamente em vigor. No Brasil, sua implementação começou em 2009, tornando-se obrigatória a partir de 2016. Entre as mudanças mais conhecidas, compreende-se que passa a ser","opcoes":["obrigatório o uso de hífen quando o prefixo (ou falso prefixo) termina em vogal e o elemento seguinte começa pela consoante r ou s: ultra-som, anti-semita, semi-reta, contra-regra etc.","facultativo o uso de hífen em locuções de qualquer tipo (nominais, adjetivas, pronominais, adverbiais, prepositivas, conjuncionais): café-da-manhã ou café da manhã, antes-de-ontem ou antes de ontem etc.","facultativo o uso de hífen quando o prefixo termina em vogal e o segundo elemento começa por vogal diferente ou consoante: auto-escola passa a se grafar autoescola, co-piloto passa a se grafar copiloto etc.","proibido o uso de hífen quando o prefixo (ou falso prefixo) termina em vogal e o elemento começa por r ou s, passando-se a dobrar a consoante do elemento seguinte: ultrassom, minissaia etc."],"correta":3,"explicacao":"Gabarito: <strong>proibido o uso de hífen quando o prefixo (ou falso prefixo) termina em vogal e o elemento começa por r ou s, passando-se a dobrar a consoante do elemento seguinte: ultrassom, minissaia etc.</strong>.","banca":"IV - UFG","ano":2026,"temas_relacionados":["fonemas","ortografia","hifen"]},{"id":4128,"enunciado":"Qual dessas palavras rima com “coração”?","opcoes":["razão","mesa","cadeira","papel"],"correta":0,"explicacao":"Gabarito: <strong>razão</strong>.","banca":"MGS","ano":2025,"temas_relacionados":["fonemas"]},{"id":4532,"enunciado":"No fragmento textual: “O voluntário via uma sequência de letras exibidas em uma tela, e tinha de dizer se cada uma era vogal ou consoante, maiúscula ou minúscula e se estava na cor verde ou vermelha”, as duas orações subordinadas introduzidas pela conjunção SE classificam-se, respectivamente, como:","opcoes":["Substantiva objetiva direta – Adverbial condicional.","Substantiva objetiva direta – Substantiva objetiva direta.","Adverbial condicional – Adverbial condicional.","Substantiva subjetiva – Adverbial modal.","Adverbial modal – Adverbial modal."],"correta":1,"explicacao":"Gabarito: <strong>Substantiva objetiva direta – Substantiva objetiva direta.</strong>.","banca":"CPCON","ano":2023,"temas_relacionados":["fonemas"]},{"id":5129,"enunciado":"Sobre a palavra “nutritiva”, é INCORRETO afirmar que:","opcoes":["É uma palavra que está no singular.","Contém 9 letras.","Contém quatro sílabas.","É uma palavra polissílaba.","Contém 5 consoantes e 5 vogais."],"correta":4,"explicacao":"Gabarito: <strong>Contém 5 consoantes e 5 vogais.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["fonemas","silabas"]},{"id":5204,"enunciado":"Na frase: “Velando está um sentinela”, a poeta optou por usar “um sentinela” ao invés de “uma sentinela”, mesmo que a forma correta gramaticalmente é a segunda. Qual alternativa explica o efeito dessa escolha lexical no poema?","opcoes":["Indica a intenção de apresentar a sentinela de uma forma mais precisa, buscando especificar o gênero masculino ou características individuais.","A escolha foi feita para manter a rima com a palavra \"está\".","A poeta desconsiderou as regras gramaticais por descuido.","A poeta buscou criar ambiguidade na identidade de quem está velando.","A opção por \"um\" tem o propósito de enfatizar o aspecto genérico da palavra."],"correta":0,"explicacao":"Gabarito: <strong>Indica a intenção de apresentar a sentinela de uma forma mais precisa, buscando especificar o gênero masculino ou características individuais.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["fonemas"]},{"id":5432,"enunciado":"Dentre as ocorrências da vogal “O” identificadas entre colchetes no quinto parágrafo do texto, quantas pertencem à classe dos artigos?","opcoes":["2","4","5","7"],"correta":2,"explicacao":"Gabarito: <strong>5</strong>.","banca":"ADM&TEC","ano":2024,"temas_relacionados":["fonemas"]},{"id":5723,"enunciado":"Analise as assertivas com V (Verdadeiro) ou F(Falso). (__)A frase nominal: \"A função social da escola\" é formada por artigo definido que concorda com o substantivo comum e com adjetivo uniforme; por uma contração prepositiva imposta pela regência nominal e por um substantivo simples. (__)O título do texto exemplifica período simples, porque a oração é absoluta escrita com sujeito simples. (__)A sílaba \"rão\" da palavra \"serão\"\" é formada por uma consoante, uma vogal nasal e uma semivogal oral. (__)No trecho: \"Quando se pensa na função social da escola\" - temos oração subordinada adverbial temporal reduzida do gerúndio, uso de próclise, duas contrações prepositivas impostas pela regência nominal. (__)A sílaba \"mei\" da palavra \"primeira\" é formada por uma consoante bilabial, uma vogal e uma semivogal. Após análise, assinale a alternativa que apresenta a sequência CORRETA dos itens acima, de cima para baixo:","opcoes":["V, V, F, F, V.","F, V, F, V, F.","V, F, V, F, V.","V, V, V, V, V."],"correta":2,"explicacao":"Gabarito: <strong>V, F, V, F, V.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["fonemas","silabas"]},{"id":5990,"enunciado":"Leia o texto '“O” Covid-19 ou “A” Covid-19? Fatos linguísticos em tempos de pandemia' e, em seguida, analise as afirmativas a seguir: I. No fragmento “... quando surgem novidades na língua, como a que estou comentando”, o artigo “a” assume função de pronome (como esta que estou comentando), assim como acontece no trecho “A isso só um aprofundamento na questão poderia responder”. II. O autor supõe que a presença de um numeral (19), assim como a pronúncia do português brasileiro, de forma geral, que acrescenta a vogal [i], após a consoante “d”, faz com que haja uma tendência para o uso de “Covid-19” no “masculino”. Parte dessa hipótese pode estar baseada na análise de palavras como boi, croqui, abacaxi e herói (as quais não foram retiradas do texto). Marque a alternativa CORRETA:","opcoes":["As duas afirmativas são verdadeiras.","A afirmativa I é verdadeira, e a II é falsa.","A afirmativa II é verdadeira, e a I é falsa.","As duas afirmativas são falsas."],"correta":2,"explicacao":"Gabarito: <strong>A afirmativa II é verdadeira, e a I é falsa.</strong>.","banca":"ADM&TEC","ano":2020,"temas_relacionados":["fonemas"]},{"id":6048,"enunciado":"Sobre os elementos linguísticos usados no texto, é verdadeiro o que se afirma em","opcoes":["“ou” (L.12) expressa ideia de acréscimo.","“há” (L.51) pode substituir “existe” (L.26) sem prejuízo de ordem gramatical, o mesmo não ocorre em relação à troca de “existe” (L.26) por “há” (L.38), tendo-se em vista o contexto em que ambas se encontram.","A preposição “de”, em “Apesar de a falta de recursos levar a uma maior inteligência emocional” (L.27), pode ser contraída com o artigo “a”, ocasionando “da”, sem constituir um desvio gramatical da norma padrão culta da língua.","Em “há” (L.51), o “-h” representa uma consoante brasileira."],"correta":1,"explicacao":"Gabarito: <strong>“há” (L.51) pode substituir “existe” (L.26) sem prejuízo de ordem gramatical, o mesmo não ocorre em relação à troca de “existe” (L.26) por “há” (L.38), tendo-se em vista o contexto em que ambas se encontram.</strong>.","banca":"Crescer Concursos","ano":2019,"temas_relacionados":["fonemas"]},{"id":6421,"enunciado":"Considere a frase abaixo, extraída do texto, e analise as assertivas que a sucedem, à luz de aspectos fonológicos, morfológicos e sintáticos da Língua Portuguesa: Gestores enfrentam desafios complexos para promover a sustentabilidade urbana, ... I. promover pertence à terceira conjugação, uma vez que se relaciona semanticamente ao sujeito Gestores. II. Em complexos, a letra x representa a sequência fonêmica /ks/, correspondendo a dois fonemas consonantais. III. O vocábulo urbana cumpre função adjetiva, por atribuir característica ao substantivo sustentabilidade.. Está CORRETO o que se afirma em","opcoes":["I, ll e III.","I e lll, apenas.","II e III, apenas.","III, apenas."],"correta":2,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["fonemas"]},{"id":6430,"enunciado":"Considerando o trecho a seguir, retirado do texto, assinale a alternativa INCORRETA sobre palavra “humilde”: “Clarice Lispector deu à humilde galinha um inesperado momento de glória”.","opcoes":["Trata-se de um adjetivo.","Apresenta o mesmo número de letras e fonemas.","Um antônimo possível seria “arrogante”.","Trata-se de palavra paroxítona."],"correta":1,"explicacao":"Gabarito: <strong>Apresenta o mesmo número de letras e fonemas.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["fonemas","paroxitonas"]},{"id":6765,"enunciado":"Sobre a voz verbal da oração “Mosquitos causam a maioria das mortes no mundo” assinale a alternativa correta.","opcoes":["Voz passiva sintética.","Voz reflexiva.","Voz passiva analítica.","Voz ativa.","Voz reflexiva recíproca."],"correta":3,"explicacao":"Gabarito: <strong>Voz ativa.</strong>.","banca":"Instituto UniFil","ano":2026,"temas_relacionados":["fonemas"]},{"id":6774,"enunciado":"Considerando os sentidos e aspectos linguísticos do texto precedente, julgue o item a seguir. Estaria mantida a correção gramatical do texto caso a forma verbal \"gastaram\" (segundo período do primeiro parágrafo) fosse flexionada na terceira pessoa do singular — gastou.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":6831,"enunciado":"Assinale a alternativa que preenche, CORRETA e respectivamente, as lacunas do texto de acordo com a norma-padrão da Língua Portuguesa.","opcoes":["é formado; compõe; trouxeram.","são formados; compõe; trouxe.","são formados; compõem; trouxe.","é formado; compõem; trouxe.","é formado; compõem; trouxeram."],"correta":4,"explicacao":"Gabarito: <strong>é formado; compõem; trouxeram.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["fonemas"]},{"id":6835,"enunciado":"The underlined verb phrase in “The team compiling the dictionary say that [...]\" correctly agrees with the subject. This does NOT happen in:","opcoes":["He is one of the best doctors who have worked here.","Ten miles is a long way to run even if I'm not tired.","The young has been under pressure suffering from anxiety.","A couple of passengers were frightened because of turbulence.","Half of the victims intend to sue the company after the accident."],"correta":2,"explicacao":"Gabarito: <strong>The young has been under pressure suffering from anxiety.</strong>.","banca":"Marinha","ano":2026,"temas_relacionados":["fonemas"]},{"id":6846,"enunciado":"Considerando os trechos a seguir, retirados do texto, assinale a alternativa na qual se identifique o emprego de voz passiva.","opcoes":["“Embora tenha ganhado grande visibilidade pública”.","“a comunidade internacional também tem discutido abordagens”.","“e interfaces que demandem níveis reduzidos de letramento digital”.","“A inteligência artificial (IA) pode ser definida como um conjunto de sistemas”."],"correta":3,"explicacao":"Gabarito: <strong>“A inteligência artificial (IA) pode ser definida como um conjunto de sistemas”.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["fonemas"]},{"id":6872,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item seguinte. No fragmento “Porém, apenas 69% confiam que a due diligence das empresas é adequada para identificar e evitar essas relações perigosas.”, a forma verbal “confiam” poderia ser flexionada no singular, visto que o seu respectivo sujeito apresenta numeral percentual sem especificador.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":6884,"enunciado":"Em \"Há iniciativas, inclusive, que buscam apurar tais vulnerabilidades\" (último parágrafo do texto 1A16), a forma verbal \"Há\" poderia ser substituída, sem prejuízo da correção gramatical, por","opcoes":["Existe.","Existem.","Acontece.","Ocorre.","Têm."],"correta":1,"explicacao":"Gabarito: <strong>Existem.</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["fonemas"]},{"id":6891,"enunciado":"Assinale a alternativa em que a forma verbal destacada está empregada corretamente, de acordo com a norma-padrão da Língua Portuguesa.","opcoes":["Só aceitarei a proposta se você ver todos os documentos antes.","Quando eu puser o projeto em prática, avisarei a equipe.","Caso ele fazer o pagamento hoje, liberaremos o material.","Não sairemos enquanto você não trazer a autorização assinada."],"correta":1,"explicacao":"Gabarito: <strong>Quando eu puser o projeto em prática, avisarei a equipe.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["fonemas"]},{"id":6905,"enunciado":"O menino mantém sua busca em alta intensidade, não acatando as sugestões dos companheiros. Transpondo a frase acima para a voz passiva, seus verbos assumem as seguintes formas:","opcoes":["seria mantida - não mais as acataria","é mantida - não sendo acatadas","sendo mantida - sem mais as acatar","tem mantido - não tendo acatado","estará mantendo - deixando de acatar"],"correta":1,"explicacao":"Gabarito: <strong>é mantida - não sendo acatadas</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["fonemas"]},{"id":6914,"enunciado":"No trecho retirado do texto “Relaxar, ler um livro, tomar um chá e ter um bom colchão são dicas importantes para um sono tranquilo”, há quantos verbos?","opcoes":["Um.","Dois.","Quatro.","Cinco."],"correta":3,"explicacao":"Gabarito: <strong>Cinco.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["fonemas"]},{"id":7379,"enunciado":"Considere os aspectos morfossintáticos, semânticos e fonológicos do período abaixo, extraído do segundo parágrafo do texto: Entretanto, esse desempenho deve ser comemorado com ressalvas... Com base nisso, assinale a alternativa que apresenta uma análise gramatical INCORRETA.","opcoes":["comemorado integra uma locução verbal e encontra-se flexionado em sua forma nominal de gerúndio.","ressalvas apresenta nove letras e oito fonemas, uma vez que a ocorrência do dígrafo consonantal \"ss\" faz com que duas letras representem um único som.","Entretanto atua como um conectivo adversativo, podendo ser substituído por Contudo ou Todavia sem prejuízo para a coerência do texto.","O termo esse classifica-se morfologicamente como um pronome demonstrativo."],"correta":0,"explicacao":"Gabarito: <strong>comemorado integra uma locução verbal e encontra-se flexionado em sua forma nominal de gerúndio.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["fonemas","digrafos"]},{"id":7519,"enunciado":"Quanto ao texto e a seus aspectos linguísticos, julgue o item a seguir. No trecho “Quando o cuidado com comunicação, voz e audição não é conduzido por um fonoaudiólogo”, a substituição de “é conduzido” por fosse conduzido preservaria o sentido original do período.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":7532,"enunciado":"No trecho “Se todas buscassem o apoio do Estado, estaríamos falando de um estádio de futebol lotado com mais de 50 mil pessoas diariamente” (l. 3-5), há uma correlação entre o tempo e o modo dos verbos (em destaque) da primeira e da segunda oração, conforme prevê a norma-padrão da língua portuguesa. O período que também constrói essa relação coerente entre tempos e modos, atendendo à norma-padrão, é:","opcoes":["A misoginia será reduzida desde que o discurso de ódio fosse condenado.","A misoginia será reduzida desde que o discurso de ódio seria condenado.","A misoginia será reduzida desde que o discurso de ódio seja condenado.","A misoginia será reduzida desde que o discurso de ódio é condenado."],"correta":2,"explicacao":"Gabarito: <strong>A misoginia será reduzida desde que o discurso de ódio seja condenado.</strong>.","banca":"CEPUERJ","ano":2026,"temas_relacionados":["fonemas"]},{"id":7534,"enunciado":"A correlação entre os tempos das formas verbais está correta somente no item: (Itens adaptados de: Inteligência artificial na educação: avanços e desafios. RNP. Disponível em: https://www.rnp.br/blog/inteligencia-artificial-na-educacao-avancos-e-desafios/ Acesso em: 31 de maio de 2026).","opcoes":["Essa foi uma movimentação que ocorreu naturalmente. Isso graças ao fato de que a inteligência artificial se apresentava como uma tecnologia que permite a realização de diferentes tarefas de forma fácil e prática.","Então, o que isso significa para o futuro da educação? Discussões sobre o tema levantassem uma série de preocupações, questionamentos e possibilidades.","No meio educacional, por exemplo, a IA se torna mais presente, a cada dia que passa, na rotina de professores, alunos e até gestores e coordenadores do meio acadêmico.","A inteligência artificial na educação é um assunto que gerou debates cada vez mais calorosos. Mas não dá para negar: o seu uso nesse meio já será uma realidade em todo o mundo."],"correta":2,"explicacao":"Gabarito: <strong>No meio educacional, por exemplo, a IA se torna mais presente, a cada dia que passa, na rotina de professores, alunos e até gestores e coordenadores do meio acadêmico.</strong>.","banca":"FCPC","ano":2026,"temas_relacionados":["fonemas"]},{"id":7551,"enunciado":"As lacunas do primeiro parágrafo devem ser correta e respectivamente preenchidas por","opcoes":["tem – tem – mantém","têm – têm – mantém","tem – têm – mantêm","têm – tem – mantêm","têm – têm – mantêm"],"correta":4,"explicacao":"Gabarito: <strong>têm – têm – mantêm</strong>.","banca":"Fundação La Salle","ano":2026,"temas_relacionados":["fonemas"]},{"id":7560,"enunciado":"Assinale a alternativa em que a frase está redigida corretamente.","opcoes":["Os trabalhadores foi embora cedo.","As casas daquela vila eram lindas.","Nós vai trabalhar muito no feriado.","Os doce da festa estava deliciosos."],"correta":1,"explicacao":"Gabarito: <strong>As casas daquela vila eram lindas.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["fonemas"]},{"id":7628,"enunciado":"O menino mantém sua busca em alta intensidade, não acatando as sugestões dos companheiros. Transpondo a frase acima para a voz passiva, seus verbos assumem as seguintes formas:","opcoes":["seria mantida — não mais acataria","é mantida — não sendo acatadas","sendo mantida — sem mais a acatar","tem mantido — não tendo acatado","estará mantendo — deixando de acatar"],"correta":1,"explicacao":"Gabarito: <strong>é mantida — não sendo acatadas</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["fonemas"]},{"id":7630,"enunciado":"O menino mantém sua busca em alta intensidade, não acatando as sugestões dos companheiros. Transpondo a frase acima para a voz passiva, seus verbos assumem as seguintes formas:","opcoes":["sendo mantida — sem mais as acatar","tem mantido — não tendo acatado","estará mantendo — deixando de acatar","seria mantida — não mais as acataria","é mantida — não sendo acatadas"],"correta":4,"explicacao":"Gabarito: <strong>é mantida — não sendo acatadas</strong>.","banca":"FCC","ano":2026,"temas_relacionados":["fonemas"]},{"id":7635,"enunciado":"Analise o período proferido pelo robô: Este é o emprego mais Iegal que já roubei! Considerando a estrutura morfossintática do período, os aspectos relacionados à voz verbal e as relações entre fonemas e grafemas presentes nas palavras do enunciado, assinale a alternativa CORRETA.","opcoes":["O verbo roubei encontra-se na voz passiva analítica, indicando que o agente da ação é a plateia humana.","Na palavra roubei, há a ocorrência de um dígrafo vocálico no segmento ou, o que reduz o número de fonemas em relação ao número de letras.","O vocábulo mais classifica-se como um advérbio de intensidade, atuando como um modificador que potencializa o sentido do adjetivo legal.","O termo já classifica-se foneticamente como um monossílabo átono e atua sintaticamente como um conectivo coordenativo explicativo."],"correta":2,"explicacao":"Gabarito: <strong>O vocábulo mais classifica-se como um advérbio de intensidade, atuando como um modificador que potencializa o sentido do adjetivo legal.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["fonemas"]},{"id":7645,"enunciado":"Assinale a alternativa que apresenta a correta transposição da frase \"O projeto foi elaborado pelos professores\" para a voz ativa:","opcoes":["Os professores elaboraram o projeto.","O projeto elaborou os professores.","Os professores foram elaborados pelo projeto.","O projeto havia sido elaborado pelos professores."],"correta":0,"explicacao":"Gabarito: <strong>Os professores elaboraram o projeto.</strong>.","banca":"Estágios CIN","ano":2026,"temas_relacionados":["fonemas"]},{"id":7663,"enunciado":"Assinale a alternativa cujas formas verbais preenchem corretamente as lacunas abaixo, na mesma ordem: - ________ muitas coisas para lhe contar. - Já ________ muitas pessoas no local da festa. - Naquele paraíso, ______tudo de bom. - Ainda ______ muitos segredos entre nós.","opcoes":["Existe - haviam - existe - haverá","Existem - haviam - existem - haverá","Existe – haviam - existem - haverão","Existem - havia - existem - haverão","Existem – havia - existe - haverá"],"correta":4,"explicacao":"Gabarito: <strong>Existem – havia - existe - haverá</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["fonemas"]},{"id":7667,"enunciado":"Estabeleça a relação entre as colunas abaixo com o preenchimento adequado das lacunas. A seguir, assinale a sequência correta obtida. (1) havia (2) haviam ( ) Em cada esquina da cidade, ____ pessoas em situação de rua. ( ) Os convidados para a cerimônia ____ perderam o melhor da festa. ( ) É certo que ____ muitas mercadorias ainda para serem entregues. (_) Sei que ____ mais de uma hora de atraso para o início da solenidade.","opcoes":["1-2-1-1","2-2-2-1","2-1-1-2","1-1-2-1","1-2-2-2"],"correta":0,"explicacao":"Gabarito: <strong>1-2-1-1</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["fonemas"]},{"id":8140,"enunciado":"Julgue o próximo item, a respeito dos sentidos e aspectos linguísticos do texto CB1A1. O termo “Conforme” (segundo período do primeiro parágrafo) poderia ser substituído por Consoante, sem prejuízo da correção gramatical e do sentido do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":8211,"enunciado":"O título Clima alentador, do editorial da Folha de S. Paulo,","opcoes":["expõe a opinião de um jornalista de sucesso.","aponta para o fracasso do compromisso de Copenha- gue.","descreve o esforço dos países ricos na redução da pobreza.","antecipa o ambiente favorável ao acordo climático.","sintetiza as conclusões do Protocolo de Kyoto."],"correta":3,"explicacao":"Gabarito: <strong>antecipa o ambiente favorável ao acordo climático.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["fonemas"]},{"id":8214,"enunciado":"No fragmento “O novo acordo precisa ir muito além de Kyoto, se a meta for impedir que o aumento da tempera- tura média da atmosfera ultrapasse 2 °C de aqueci- mento neste século, como recomenda a maioria dos climatologistas.” (A. 15-19), o termo “se” tem o sentido equi- valente ao de","opcoes":["logo que.","à medida que.","no caso de.","apesar de.","uma vez que."],"correta":2,"explicacao":"Gabarito: <strong>no caso de.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["fonemas"]},{"id":8218,"enunciado":"Leia as frases abaixo A Inglaterra aprovou uma lei pela qual o país terá de cortar em 80% ____ suas emissões de carbono. O fato de as cifras virem ____ tona antes da conferência é outro sinal alentador. Esse cipoal de números torna complexa _____ discussão em Copenhague, mas não a inviabiliza. O Presidente Barack Obama anunciou que vai _____ Copenhague e que se compromete com um corte de 17% até 2020. As palavras que, na sequência, preenchem as lacunas acima corretamente são","opcoes":["as – à – a – a.","às – à – a – a.","às – a – à – à.","as – a – a – à.","as – a – a – a."],"correta":0,"explicacao":"Gabarito: <strong>as – à – a – a.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["fonemas"]},{"id":8288,"enunciado":"O título Clima alentador, do editorial da Folha de S. Paulo,","opcoes":["expõe a opinião de um jornalista de sucesso.","aponta para o fracasso do compromisso de Copenha- gue.","descreve o esforço dos países ricos na redução da pobreza.","antecipa o ambiente favorável ao acordo climático.","sintetiza as conclusões do Protocolo de Kyoto. 3"],"correta":3,"explicacao":"Gabarito: <strong>antecipa o ambiente favorável ao acordo climático.</strong>.","banca":"CESGRANRIO","ano":2010,"temas_relacionados":["fonemas"]},{"id":8337,"enunciado":"A idéia principal do texto está expressa em:","opcoes":["O final de ano garante habitualmente maior volume de vendas, tanto à vista quanto a prazo.","A oferta mais ampla de crediários busca concorrer com o comércio popular, identificado com as vendas _________________________________________________________ de menor valor.","Negócios realizados a prazo caracterizam as vendas específicas de final de ano.","Comerciantes dispensam consultas para a conces- são de créditos, por serem baixos os valores das compras.","Cai o volume de vendas, à vista ou a crédito, neste final de ano, em comparação com o anterior."],"correta":1,"explicacao":"Gabarito: <strong>A oferta mais ampla de crediários busca concorrer com o comércio popular, identificado com as vendas _________________________________________________________ de menor valor.</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["fonemas"]},{"id":8339,"enunciado":"... a taxa de crescimento das consultas para vendas à vis- ta superou a expansão do crediário ... (final do 1 pará- grafo) A frase acima aparece reproduzida com o mesmo sentido, embora com outras palavras, em:","opcoes":["a expansão do crediário foi maior do que o cres- cimento da taxa de consultas para vendas à vista...","permanecem as taxas de ampliação do crédito, tal como o número de consultas para vendas à vista...","houve maior número de consultas para vendas à vista do que para vendas a crédito...","as consultas para vendas à vista foram superadas pela maior oferta de crediário...","é necessário haver mais crédito para também cres- cer o número de vendas à vista..."],"correta":2,"explicacao":"Gabarito: <strong>houve maior número de consultas para vendas à vista do que para vendas a crédito...</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["fonemas"]},{"id":8344,"enunciado":"... dos que opõem à tirania do essencial a validade do a existencial. (11 linha) Em outras palavras, a afirmativa transcrita acima aponta","opcoes":["a constante preocupação da universalização dos hábitos alimentares característicos de algumas so- ciedades.","a valorização das influências diariamente viven- ciadas no próprio ambiente social ou cultural.","a correta aceitação de que o gosto por determinados alimentos seja um dos aspectos fisiológicos do ser humano.","as dificuldades no desconhecimento do gosto parti- cular de alguns alimentos típicos regionais.","a desconsideração de ser a comida reflexo do gosto de toda a sociedade e não apenas de uma pessoa."],"correta":1,"explicacao":"Gabarito: <strong>a valorização das influências diariamente viven- ciadas no próprio ambiente social ou cultural.</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["fonemas"]},{"id":8345,"enunciado":"O autor, no texto em questão,","opcoes":["discute conceitos filosóficos amplamente debatidos em todas as sociedades, como a noção de verdade.","ignora a existência de certos princípios norteadores da vida social e das diversidades culturais.","nega as possíveis influências que os alimentos pos- sam exercer no desenvolvimento de uma cultura.","condena a preocupação de certos pensadores em reduzir a preferência por certos alimentos, como os doces, a um hábito social.","defende uma opinião pessoal, tomando como base idéias expostas por filósofos e escritores anteriores a ele. 3"],"correta":4,"explicacao":"Gabarito: <strong>defende uma opinião pessoal, tomando como base idéias expostas por filósofos e escritores anteriores a ele. 3</strong>.","banca":"FCC","ano":2006,"temas_relacionados":["fonemas"]},{"id":8397,"enunciado":"“A Receita Federal, em conjunto com o Ministério Público do Estado de São Paulo e Polícia Rodoviária Federal, deflagrou na manhã desta segunda-feira (7), a Operação Ceres, que visa combater complexa fraude fiscal promovida por organização criminosa atuante no segmento de produção e distribuição de cervejas. Houve a identificação da ocorrência de diversos crimes que culminaram em sonegação de tributos federais, tais como falsidade documental, falsidade ideológica e uso de interpostas pessoas jurídicas no intuito de ocultar os reais beneficiários das fraudes combatidas.” (https://www.gov.br/receitafederal/pt- br/assuntos/noticias/2022/novembro/operacao-ceres-receita-federal-executa- operacao-de-combate-a-fraudes-fiscais-estruturadas) Esse texto pertence ao gênero informativo, caracterizado predominantemente pela objetividade, que é construída pela estruturação geral do texto, com o objetivo de fornecer claramente dados da realidade. Assinale a opção que apresenta uma informação adequadamente retirada do segmento destacado.","opcoes":["“A Receita Federal, em conjunto com o Ministério Público do Estado de São Paulo e Polícia Rodoviária Federal, deflagrou na manhã desta segunda-feira (7), a Operação Ceres...” / a operação Ceres foi iniciada de forma inesperada, com um aparato de segurança bastante forte, em função da gravidade do crime detectado.","“...a Operação Ceres, que visa combater complexa fraude fiscal promovida por organização criminosa atuante no segmento de produção e distribuição de cervejas.” / o nome mitológico Ceres designa uma deusa mitológica relacionada ao trigo e a cereais, tendo sido escolhido aleatoriamente, sem qualquer relação lógica com os fatos informados.","“A Receita Federal, em conjunto com o Ministério Público do Estado de São Paulo e Polícia Rodoviária Federal...” / a operação realizada envolve investigação de atividades criminosas ligadas a espaços diversos.","“...tais como falsidade documental, falsidade ideológica e uso de interpostas pessoas jurídicas no intuito de ocultar os reais beneficiários das fraudes combatidas.” / o segmento já mostra o resultado da operação deflagrada, com a descoberta de vários tipos de fraudes.","“Houve a identificação da ocorrência de diversos crimes que culminaram em sonegação de tributos federais,” / Foram identificados vários e variados crimes, que encobriam o crime mais grave de sonegação de tributos."],"correta":2,"explicacao":"Gabarito: <strong>“A Receita Federal, em conjunto com o Ministério Público do Estado de São Paulo e Polícia Rodoviária Federal...” / a operação realizada envolve investigação de atividades criminosas ligadas a espaços diversos.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8399,"enunciado":"A língua escrita, desde que foi criada, tem uma série de distintas funções. Assim, por exemplo, a língua escrita é o veículo de muitas declarações de renda, que são armazenadas em arquivos especializados na Receita Federal. Nesse caso, a função predominante da escrita é","opcoes":["a de transferência: transferir a realização do ato comunicativo para outro lugar ou momento","a de preservação: armazenar informações para possíveis consultas futuras.","a de memorização: preservar dados para consultas no momento de pagamento.","a sócio-político-cultural: relacionar o pagamento de impostos com dados de uma sociedade civilizada.","a histórica: conservar textos de valor documentativo da evolução dos impostos no país."],"correta":1,"explicacao":"Gabarito: <strong>a de preservação: armazenar informações para possíveis consultas futuras.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8402,"enunciado":"Leia o texto a seguir, adaptado de um site informativo: “Impostos são tributos obrigatórios que o cidadão brasileiro (ou de qualquer outro país) paga para contribuir com as despesas administrativas do Estado. Entre essas despesas estão: saúde, educação, segurança, infraestrutura, alimentação e etc. Como o próprio nome já diz, os pagamentos desses tributos são impostos pelo Governo. Quando o pagamento não é feito, ele pode gerar multas ou punições legais mais graves ao cidadão, como prisão ou congelamento de documentação. ” Todos os segmentos abaixo, retirados do texto acima, mostram problemas gramaticais ou de expressão. Assinale o único segmento integralmente adequado.","opcoes":["Impostos são tributos obrigatórios que o cidadão brasileiro (ou de qualquer outro país) paga...","...paga para contribuir com as despesas administrativas do Estado.","Entre essas despesas estão: saúde, educação, segurança, infraestrutura, alimentação e etc.","Como o próprio nome já diz, os pagamentos desses tributos são impostos pelo Governo.","Quando o pagamento não é feito, ele pode gerar multas ou punições legais mais graves..."],"correta":3,"explicacao":"Gabarito: <strong>Como o próprio nome já diz, os pagamentos desses tributos são impostos pelo Governo.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8403,"enunciado":"Leia com atenção o pequeno texto abaixo: “Pagamos mais impostos em remédios do que em revistas e filmes pornográficos - Sim, isso mesmo. Enquanto revistas eróticas sofrem uma taxação de 19%, nossos remédios possuem uma carga tributária de incríveis 34%. Além de dar prioridade ao conteúdo adulto, nosso sistema tributário ainda nos trata pior do que animais: segundo o Instituto Brasileiro de Planejamento e Tributação (IBPT), medicamentos veterinários possuem uma carga tributária de 13%, quase um terço dos impostos embutidos em remédios de uso humano.” (Sete fatos impressionantes sobre os impostos no Brasil – Emanuel Steffen) Nesse texto, a crítica realizada é a de que os impostos","opcoes":["demonstram a insanidade do sistema tributário, que incentiva o consumo de revistas e filmes pornográficos.","mostram desequilíbrio na tributação, pois provocam aumento de preços em setores menos importantes.","Indicam a absoluta falta de critério na taxação de produtos mais importantes, em detrimento de outros de menor importância social.","comprovam a ilogicidade da cobrança, já que tributam mais os produtos em que deveriam cobrar menos, em comparação com outros.","privilegiam setores de menor interesse social, ao passo que cobram bastante de outros em que há interesse humano."],"correta":3,"explicacao":"Gabarito: <strong>comprovam a ilogicidade da cobrança, já que tributam mais os produtos em que deveriam cobrar menos, em comparação com outros.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8406,"enunciado":"Todas as frases abaixo têm por tema a economia. Assinale a frase que está integralmente estruturada em linguagem lógica.","opcoes":["Nesse mundo nada é inevitável, exceto a morte e os impostos.","Não importa quem governa, o mercado governa.","Acelerar a economia demais leva a uma derrapagem.","Inflação é a arte de falsificar moeda por conta do Estado.","O rico é o espetáculo predileto dos pobres."],"correta":0,"explicacao":"Gabarito: <strong>Nesse mundo nada é inevitável, exceto a morte e os impostos.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8413,"enunciado":"Text I suggests auditors should invest in more","opcoes":["dynamic surveys.","unfounded records.","provisional auditing.","constant interactions.","user-friendly programs."],"correta":3,"explicacao":"Gabarito: <strong>constant interactions.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8414,"enunciado":"The opposite of quietness (3rd paragraph) is","opcoes":["deafness.","loudness.","kindliness.","dampness.","shrewdness."],"correta":1,"explicacao":"Gabarito: <strong>loudness.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8415,"enunciado":"“Unless” in “unless it can stake a stronger claim to supporting improvement” (7th paragraph) introduces a(n)","opcoes":["plea.","averral.","account.","foresight.","condition. Text II Global commerce Driverless vehicles whizz across five new berths at Tuas Mega Port, which sits on a swathe of largely reclaimed land at the western tip of Singapore. Unmanned cranes loom overhead, circled by camera-fitted drones. The berths are the first of 21 due by 2027. When it is completed in 2040, the complex will be the largest container port on Earth, boasts PSA International, its Singaporean owner. Tuas is a vision of the future on two fronts. It illustrates how port operators the world over are deploying clever technologies to meet the demand for their services in the face of obstacles to the development of new facilities, from lack of space to environmental concerns. More fundamentally, the city-state’s investment, with construction costs estimated at $15bn, is part of a wave of huge bets by the broader logistics industry on the rising importance of Asia, and South-East Asia in particular. The IMF expects the region’s five largest economies—Indonesia, Malaysia, Singapore, the Philippines and Thailand—to be the fastest-growing bloc in the world by trade volumes between 2022 and 2027. The result is that the map of global commerce and the blueprints for its critical nodes are being simultaneously redrawn. From: The Economist, January 14, 2023, pp. 57-58"],"correta":4,"explicacao":"Gabarito: <strong>condition. Text II Global commerce Driverless vehicles whizz across five new berths at Tuas Mega Port, which sits on a swathe of largely reclaimed land at the western tip of Singapore. Unmanned cranes loom overhead, circled by camera-fitted drones. The berths are the first of 21 due by 2027. When it is completed in 2040, the complex will be the largest container port on Earth, boasts PSA International, its Singaporean owner. Tuas is a vision of the future on two fronts. It illustrates how port operators the world over are deploying clever technologies to meet the demand for their services in the face of obstacles to the development of new facilities, from lack of space to environmental concerns. More fundamentally, the city-state’s investment, with construction costs estimated at $15bn, is part of a wave of huge bets by the broader logistics industry on the rising importance of Asia, and South-East Asia in particular. The IMF expects the region’s five largest economies—Indonesia, Malaysia, Singapore, the Philippines and Thailand—to be the fastest-growing bloc in the world by trade volumes between 2022 and 2027. The result is that the map of global commerce and the blueprints for its critical nodes are being simultaneously redrawn. From: The Economist, January 14, 2023, pp. 57-58</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8417,"enunciado":"The overall position of the article is rather","opcoes":["flimsy.","gloomy.","scornful.","awkward.","supportive."],"correta":4,"explicacao":"Gabarito: <strong>supportive.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8418,"enunciado":"The machines described in the first paragraph","opcoes":["look somewhat rickety.","have recently come apart.","obviate physical exertion.","are too strenuous to be run.","were devised by Asian laymen."],"correta":2,"explicacao":"Gabarito: <strong>obviate physical exertion.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8419,"enunciado":"The sentence “Driverless vehicles whizz across” (1st paragraph) introduces a sense of","opcoes":["speed.","height.","weight.","depth.","size."],"correta":0,"explicacao":"Gabarito: <strong>speed.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8420,"enunciado":"The use of the verb “loom” in “Unmanned cranes loom overhead” (1st paragraph) helps build an atmosphere that is rather","opcoes":["flattering.","reassuring.","heartening.","frightening.","enchanting."],"correta":3,"explicacao":"Gabarito: <strong>frightening.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8421,"enunciado":"The word “swathe” (1st paragraph) can also be used elsewhere in the relation to","opcoes":["lather.","cloth.","foam.","tide.","fire. Raciocínio Lógico Matemático e"],"correta":1,"explicacao":"Gabarito: <strong>cloth.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8475,"enunciado":"Observe a estruturação das três frases abaixo: - Pagaram o imposto no prazo. - Pagou-se o imposto no prazo. - Alguém pagou o imposto no prazo. Sobre essa estruturação, assinale a afirmação correta.","opcoes":["As duas primeiras frases estão na voz passiva.","Em todas as frases o sujeito não é identificado.","As duas últimas frases mostram o agente da ação verbal.","O sujeito é indeterminado na terceira frase.","As duas últimas frases mostram sujeito claro."],"correta":4,"explicacao":"Gabarito: <strong>As duas últimas frases mostram sujeito claro.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8476,"enunciado":"Sabemos todos que a repetição de palavras idênticas num texto é um problema sempre corrigido pelos professores de redação. Assinale a frase abaixo em que a repetição de palavras idênticas não é identificada como um problema de escrita.","opcoes":["O ruim de ser incluído entre os ricos é viver com os ricos.","Como a maior parte dos ricos, o principal uso da riqueza consiste na exibição da riqueza.","Um idiota pobre é um idiota. Um idiota rico é um rico.","Ame teu vizinho, mas não derrube a cerca do teu vizinho.","O que a Câmara faz, faz a Câmara. Língua Inglesa Text I Adding ethics to public finance Evolutionary moral psychologists point the way to garnering broader support for fiscal policies Policy decisions on taxation and public expenditures intrinsically reflect moral choices. How much of your hard-earned money is it fair for the state to collect through taxes? Should the rich pay more? Should the state provide basic public services such as education and health care for free to all citizens? And so on. Economists and public finance practitioners have traditionally focused on economic efficiency. When considering distributional issues, they have generally steered clear of moral considerations, perhaps fearing these could be seen as subjective. However, recent work by evolutionary moral psychologists suggests that policies can be better designed and muster broader support if policymakers consider the full range of moral perspectives on public finance. A few pioneering empirical applications of this approach in the field of economics have shown promise. For the most part, economists have customarily analyzed redistribution in a way that requires users to provide their own preferences with regard to inequality: Tell economists how much you care about inequality, and they can tell you how much redistribution is appropriate through the tax and benefit system. People (or families or households) have usually been considered as individuals, and the only relevant characteristics for these exercises have been their incomes, wealth, or spending potential. There are two — understandable but not fully satisfactory — reasons for this approach. First, economists often wish to be viewed as objective social scientists. Second, most public finance scholars have been educated in a tradition steeped in values of societies that are WEIRD (Western, Educated, Industrialized, Rich, and Democratic). In this context, individuals are at the center of the analysis, and morality is fundamentally about the golden rule — treat other people the way that you would want them to treat you, regardless of who those people are. These are crucial but ultimately insufficient perspectives on how humans make moral choices. Evolutionary moral psychologists during the past couple of decades have shown that, faced with a moral dilemma, humans decide quickly what seems right or wrong based on instinct and later justify their decision through more deliberate reasoning. Based on evidence presented by these researchers, our instincts in the moral domain evolved as a way of fostering cooperation within a group, to help ensure survival. This modern perspective harks back to two moral philosophers of the Scottish Enlightenment — David Hume and Adam Smith — who noted that sentiments are integral to people’s views on right and wrong. But most later philosophers in the Western tradition sought to base morality on reason alone. Moral psychologists have recently shown that many people draw on moral perspectives that go well beyond the golden rule. Community, authority, divinity, purity, loyalty, and sanctity are important considerations not only in many non-Western countries, but also among politically influential segments of the population in advanced economies, as emphasized by proponents of moral foundations theory. Regardless of whether one agrees with those broader moral perspectives, familiarity with them makes it easier to understand the underlying motivations for various groups’ positions in debates on public policies. Such understanding may help in the design of policies that can muster support from a wide range of groups with differing moral values. Adapted from: https://www.imf.org/en/Publications/fandd/issues/2022/03/Adding- ethics-to-public-finance-Mauro"],"correta":4,"explicacao":"Gabarito: <strong>O que a Câmara faz, faz a Câmara. Língua Inglesa Text I Adding ethics to public finance Evolutionary moral psychologists point the way to garnering broader support for fiscal policies Policy decisions on taxation and public expenditures intrinsically reflect moral choices. How much of your hard-earned money is it fair for the state to collect through taxes? Should the rich pay more? Should the state provide basic public services such as education and health care for free to all citizens? And so on. Economists and public finance practitioners have traditionally focused on economic efficiency. When considering distributional issues, they have generally steered clear of moral considerations, perhaps fearing these could be seen as subjective. However, recent work by evolutionary moral psychologists suggests that policies can be better designed and muster broader support if policymakers consider the full range of moral perspectives on public finance. A few pioneering empirical applications of this approach in the field of economics have shown promise. For the most part, economists have customarily analyzed redistribution in a way that requires users to provide their own preferences with regard to inequality: Tell economists how much you care about inequality, and they can tell you how much redistribution is appropriate through the tax and benefit system. People (or families or households) have usually been considered as individuals, and the only relevant characteristics for these exercises have been their incomes, wealth, or spending potential. There are two — understandable but not fully satisfactory — reasons for this approach. First, economists often wish to be viewed as objective social scientists. Second, most public finance scholars have been educated in a tradition steeped in values of societies that are WEIRD (Western, Educated, Industrialized, Rich, and Democratic). In this context, individuals are at the center of the analysis, and morality is fundamentally about the golden rule — treat other people the way that you would want them to treat you, regardless of who those people are. These are crucial but ultimately insufficient perspectives on how humans make moral choices. Evolutionary moral psychologists during the past couple of decades have shown that, faced with a moral dilemma, humans decide quickly what seems right or wrong based on instinct and later justify their decision through more deliberate reasoning. Based on evidence presented by these researchers, our instincts in the moral domain evolved as a way of fostering cooperation within a group, to help ensure survival. This modern perspective harks back to two moral philosophers of the Scottish Enlightenment — David Hume and Adam Smith — who noted that sentiments are integral to people’s views on right and wrong. But most later philosophers in the Western tradition sought to base morality on reason alone. Moral psychologists have recently shown that many people draw on moral perspectives that go well beyond the golden rule. Community, authority, divinity, purity, loyalty, and sanctity are important considerations not only in many non-Western countries, but also among politically influential segments of the population in advanced economies, as emphasized by proponents of moral foundations theory. Regardless of whether one agrees with those broader moral perspectives, familiarity with them makes it easier to understand the underlying motivations for various groups’ positions in debates on public policies. Such understanding may help in the design of policies that can muster support from a wide range of groups with differing moral values. Adapted from: https://www.imf.org/en/Publications/fandd/issues/2022/03/Adding- ethics-to-public-finance-Mauro</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8478,"enunciado":"In the subtitle, “garnering” comes from the notion of","opcoes":["storing grains.","renting garrets.","making garlands.","lapidating garnets.","charging garrisons."],"correta":0,"explicacao":"Gabarito: <strong>storing grains.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8479,"enunciado":"The adjective in “is it fair for the state to collect through taxes” (1st paragraph) is equivalent in meaning to","opcoes":["bewildering.","befuddling.","bemusing.","beguiling.","befitting."],"correta":4,"explicacao":"Gabarito: <strong>befitting.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8480,"enunciado":"The underlined expression in “regardless of who those people are” (4th paragraph) can be replaced without change in meaning by","opcoes":["alike.","despite.","whereas.","however.","concerning."],"correta":1,"explicacao":"Gabarito: <strong>despite.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8481,"enunciado":"When it is stated that “tradition [is] steeped in values of societies” (4th paragraph) it is implied that these values have been","opcoes":["imbued.","shunned.","debased.","withheld.","overestimated. Text II How trade can become a gateway to climate resilience Most people don't think about climate change when they lift a café latte to their lips or nibble on a square of chocolate — but this could soon change. Based on current trajectories, around a quarter of Brazil’s coffee farms and 37% of Indonesia’s are likely to be lost to climate change. Swathes of Ghana and Côte d’Ivoire — where most of the world’s chocolate is sourced — will become too hot to grow cocoa by 2050. Climate-related droughts and deadly heatwaves across the world have coincided with severe storms, cyclones, hurricanes, and, of course, a pandemic. As a consequence of these shocks, millions of people have been left without homes, and a growing number of people now face starvation and a total collapse of livelihoods as growing and exporting staple crops becomes untenable. We must immediately rethink the shape of our economies, agricultural systems and consumption patterns. Our priority is to manufacture climate resilience in global economies and societies — and we must do it quickly. Trade can kickstart the emergence of climate-resilient economies, especially in the poorest countries. Trade has a multiplier effect on economies by driving production growth and fostering the expansion of export industries. By shifting focus to production and exports that increase climate resilience, there is potential to exponentially increase the land surface and trade processes prepared to withstand the climate crisis. Adapted from: https://www.weforum.org/agenda/2022/07/trade-can-be-a- gateway-to-climate-resilience"],"correta":0,"explicacao":"Gabarito: <strong>imbued.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8482,"enunciado":"The aim of the text is to offer both","opcoes":["an alert and a scolding.","a query and a dismissal.","a pledge and a grievance.","a warning and a way out.","a disclaimer and a solution."],"correta":3,"explicacao":"Gabarito: <strong>a warning and a way out.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8483,"enunciado":"The position of the writer is that the situation described","opcoes":["could be shrugged off.","will not offer any harm.","ought to shift promptly.","should be taken lightly.","needs to be overlooked."],"correta":2,"explicacao":"Gabarito: <strong>ought to shift promptly.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8484,"enunciado":"The adjective in “the poorest countries” (5th paragraph) is in the same form as","opcoes":["All nations should be more attentive to the homeless.","Ghana will be having a fine chocolate harvest in 2050.","Brazil is one amongst many coffee-producing countries.","It is hard to point out the most comfortable places on Earth.","Hopefully by 2050 there will be fewer climate-related issues."],"correta":3,"explicacao":"Gabarito: <strong>It is hard to point out the most comfortable places on Earth.</strong>.","banca":"FGV","ano":2023,"temas_relacionados":["fonemas"]},{"id":8547,"enunciado":"O objetivo principal do texto é discutir a","opcoes":["contraposição entre a agricultura orgânica e a conven- cional, baseada no uso de agrotóxicos.","implementação de monoculturas para a renovação do bem-sucedido modelo agrário brasileiro.","importância de o nosso país se manter na liderança na concorrência mundial do agronegócio.","intoxicação dos trabalhadores e a contaminação am- biental provocados pela agricultura familiar.","perspectiva de o agronegócio conseguir produzir ali- mentos para uma população de sete bilhões de pes- soas."],"correta":0,"explicacao":"Gabarito: <strong>contraposição entre a agricultura orgânica e a conven- cional, baseada no uso de agrotóxicos.</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["fonemas"]},{"id":8551,"enunciado":"No trecho “ao acordar do sonho de uma economia agrá- ria pujante, o país desperta para o pesadelo de ser, pelo quinto ano consecutivo, o maior consumidor de agrotóxi- cos do planeta” (parágrafo 1), a palavra destacada pode ser substituída, sem prejuízo do sentido, por","opcoes":["apreciada","incipiente","inoperante","possante","moderna"],"correta":3,"explicacao":"Gabarito: <strong>possante</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["fonemas"]},{"id":8552,"enunciado":"No trecho “Esses venenos seriam, portanto, um mal ne- cessário, de acordo com esses produtores.” (parágrafo 6), a palavra destacada veicula a relação lógica de","opcoes":["adição","conclusão","concessão","explicação","temporalidade"],"correta":1,"explicacao":"Gabarito: <strong>conclusão</strong>.","banca":"CESGRANRIO","ano":2023,"temas_relacionados":["fonemas"]},{"id":1973791,"enunciado":"Considerando as ideias do texto CG3A1-I, julgue o seguinte item. \n\n\n\n\nConsoante a perspectiva defendida no texto, a abundância de comodidades na vida moderna promove uma sujeição desnecessária das pessoas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["fonemas"]},{"id":2360388,"enunciado":"Considerando os sentidos e os aspectos linguísticos do texto, julgue o item.\n\n\n\n\nA utilização do termo “Segundo o” (linha 22) imprime no texto uma característica mais formal, uma vez que evidencia o embasamento do que se afirma a seguir. Com esse mesmo propósito, pode‑se substituir o termo destacado por seus sinônimos de acordo com o, conforme, consoante ou em conformidade com o, sem que haja prejuízo ao sentido original e à correção gramatical do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["fonemas"]}];
